window.BOOK={"title_en": "Watson's Notebook", "title_ko": "왓슨의 사건 수첩", "sub": "셜록 홈즈의 세 사건", "cover": "img/c0_a.svg", "toc": [{"n": 0, "label": "프롤로그", "title_en": "My Friend, Sherlock Holmes", "title_ko": "내 친구 셜록 홈즈", "work": "새로 쓴 글", "ready": true}, {"n": 1, "label": "1장", "title_en": "Red Hair Wanted", "title_ko": "빨간 머리만 오세요", "work": "빨간 머리 연맹", "ready": true}, {"n": 2, "label": "2장", "title_en": "The League Is Gone", "title_ko": "사라진 연맹", "work": "빨간 머리 연맹", "ready": true}, {"n": 3, "label": "3장", "title_en": "Waiting in the Dark", "title_ko": "어둠 속에서 기다리기", "work": "빨간 머리 연맹", "ready": true}, {"n": 4, "label": "4장", "title_en": "A Hat and a Goose", "title_ko": "모자 하나, 거위 한 마리", "work": "푸른 석류석", "ready": true}, {"n": 5, "label": "5장", "title_en": "The Stone in the Goose", "title_ko": "거위 속의 보석", "work": "푸른 석류석", "ready": true}, {"n": 6, "label": "6장", "title_en": "Follow the Goose", "title_ko": "거위를 따라가라", "work": "푸른 석류석", "ready": true}, {"n": 7, "label": "7장", "title_en": "The Missing Horse", "title_ko": "사라진 우승 후보", "work": "실버 블레이즈", "ready": true}, {"n": 8, "label": "8장", "title_en": "What Was in His Pockets", "title_ko": "주머니 속 물건들", "work": "실버 블레이즈", "ready": true}, {"n": 9, "label": "9장", "title_en": "The Dog in the Night", "title_ko": "밤중의 개", "work": "실버 블레이즈", "ready": true}, {"n": 10, "label": "10장", "title_en": "The Horse with No White Face", "title_ko": "흰 이마가 사라진 말", "work": "실버 블레이즈", "ready": true}, {"n": 11, "label": "에필로그", "title_en": "Your Turn, Detective", "title_ko": "이제 네 차례야", "work": "새로 쓴 글", "ready": true}], "chapters": {"0": {"n": 0, "label": "프롤로그", "title_en": "My Friend, Sherlock Holmes", "title_ko": "내 친구 셜록 홈즈", "new_text": false, "source": "이 장은 원작에 없는 글이에요. 세 사건을 한 권으로 묶으려고 새로 썼어요. 사건 내용은 넣지 않았고, 원작에서 확인되는 사실만 썼어요.", "recap_title": "시작하기 전에", "recap": ["이 책을 들려주는 사람은 의사 왓슨이에요. 왓슨은 친구 셜록 홈즈와 함께한 사건을 수첩에 적어 두었어요. 오늘은 왓슨이 자기와 홈즈를 소개하고, 여러분에게도 수첩을 하나 건네요."], "cards": [{"en": "Sherlock Holmes", "ko": "셜록 홈즈", "new": false, "line": "런던 베이커 가 221B에 사는 탐정이에요. 남들이 그냥 지나치는 작은 것을 알아차려요.", "img": "img/p_holmes.jpg"}, {"en": "Watson", "ko": "왓슨", "new": false, "line": "의사이고, 홈즈의 친구예요. 이 책에서 '나(I)'로 이야기를 들려줘요. 홈즈와 같이 사건을 겪고, 끝나면 수첩에 적어 둬요.", "img": "img/p_watson.jpg"}], "words": [{"w": "detective", "ko": "탐정", "ex": "Holmes is a detective.", "why": "이 책의 주인공 홈즈가 하는 일이에요.", "src": "audio/w_detective.mp3", "exsrc": "audio/c0_v0.mp3"}, {"w": "notice", "ko": "알아차리다", "ex": "He notices small things.", "why": "홈즈가 남들과 다른 점이 바로 이거예요.", "src": "audio/w_notice.mp3", "exsrc": "audio/c0_v1.mp3"}, {"w": "clue", "ko": "단서", "ex": "When you find a clue, write it down.", "why": "사건을 푸는 열쇠예요. 책 끝까지 계속 나와요.", "src": "audio/w_clue.mp3", "exsrc": "audio/c0_v2.mp3"}, {"w": "notebook", "ko": "수첩", "ex": "I write it down in my notebook.", "why": "왓슨에게도, 여러분에게도 수첩이 있어요. 단서는 여기에 모아요.", "src": "audio/w_notebook.mp3", "exsrc": "audio/c0_v3.mp3"}], "scenes": [{"no": 1, "title": "작은 것을 보는 탐정", "paras": [{"kind": "p", "units": [{"t": "My name is Watson.", "sp": "Watson", "src": "audio/c0_1_00_00.mp3"}, {"t": "I am a doctor, and I am a friend of Mr. Sherlock Holmes.", "sp": "Watson", "src": "audio/c0_1_00_01.mp3"}]}, {"kind": "p", "units": [{"t": "Holmes is a detective.", "sp": "Watson", "src": "audio/c0_1_01_00.mp3"}, {"t": "He lives in London, at 221B Baker Street.", "sp": "Watson", "src": "audio/c0_1_01_01.mp3"}, {"t": "People come to his room with strange problems.", "sp": "Watson", "src": "audio/c0_1_01_02.mp3"}]}, {"kind": "p", "units": [{"t": "Holmes listens to their stories.", "sp": "Watson", "src": "audio/c0_1_02_00.mp3"}, {"t": "Then he looks carefully.", "sp": "Watson", "src": "audio/c0_1_02_01.mp3"}, {"t": "He looks at their hands and their clothes.", "sp": "Watson", "src": "audio/c0_1_02_02.mp3"}, {"t": "He notices small things.", "sp": "Watson", "src": "audio/c0_1_02_03.mp3"}, {"t": "Other people miss these things, but Holmes sees them.", "sp": "Watson", "src": "audio/c0_1_02_04.mp3"}]}, {"kind": "p", "units": [{"t": "\"The little things are the most important,\"", "sp": "Holmes", "src": "audio/c0_1_03_00.mp3"}, {"t": "he says.", "sp": "Watson", "src": "audio/c0_1_03_01.mp3"}]}], "check": {"q": "홈즈는 사람들을 만나면 무엇을 볼까요?", "a": "손이나 옷처럼 작은 것을 꼼꼼히 봐요. 다른 사람들은 그냥 지나치는 것들이에요."}, "imgs": [{"at": 0, "src": "img/c0_a.svg"}]}, {"no": 2, "title": "너에게도 수첩을 줄게", "paras": [{"kind": "p", "units": [{"t": "I often go with Holmes on his cases.", "sp": "Watson", "src": "audio/c0_2_00_00.mp3"}, {"t": "When a case is over, I write it down in my notebook.", "sp": "Watson", "src": "audio/c0_2_00_01.mp3"}]}, {"kind": "p", "units": [{"t": "In this book, I will tell you three of his cases.", "sp": "Watson", "src": "audio/c0_2_01_00.mp3"}, {"t": "There is a man with very red hair.", "sp": "Watson", "src": "audio/c0_2_01_01.mp3"}, {"t": "There is a lost Christmas goose.", "sp": "Watson", "src": "audio/c0_2_01_02.mp3"}, {"t": "And there is a famous horse that disappeared.", "sp": "Watson", "src": "audio/c0_2_01_03.mp3"}]}, {"kind": "p", "units": [{"t": "Here is a notebook for you, too.", "sp": "Watson", "src": "audio/c0_2_02_00.mp3"}, {"t": "When you find a clue, write it down.", "sp": "Watson", "src": "audio/c0_2_02_01.mp3"}, {"t": "Before Holmes explains a case, stop and think.", "sp": "Watson", "src": "audio/c0_2_02_02.mp3"}, {"t": "Can you solve it first?", "sp": "Watson", "src": "audio/c0_2_02_03.mp3"}]}, {"kind": "p", "units": [{"t": "Are you ready?", "sp": "Watson", "src": "audio/c0_2_03_00.mp3"}, {"t": "Then let us begin.", "sp": "Watson", "src": "audio/c0_2_03_01.mp3"}]}], "check": {"q": "왓슨은 여러분에게 무엇을 하라고 했나요?", "a": "단서를 찾으면 수첩에 적고, 홈즈가 설명하기 전에 멈춰서 먼저 풀어 보라고 했어요."}, "imgs": []}], "solve": null, "solve_answers": [], "clues": [], "clue_intro": "", "quiz": [], "record": [], "think": "", "reflect": null, "cert": null, "end": null, "words_read": 164}, "1": {"n": 1, "label": "1장", "title_en": "Red Hair Wanted", "title_ko": "빨간 머리만 오세요", "new_text": false, "source": "원작: 아서 코난 도일, 「빨간 머리 연맹(The Red-Headed League)」, 『셜록 홈즈의 모험』(Project Gutenberg #1661, 1138~1560행). 초6 눈높이(CEFR A2~B1 초반)로 쉽게 고쳐 쓴 글이에요.", "recap_title": "사건 소개", "recap": ["머리카락이 빨갛다는 이유 하나로 돈을 주겠다는 신문 광고가 있었어요. 그 광고를 보고 찾아간 윌슨 씨는 정말로 일자리를 얻었어요. 그런데 왜 홈즈를 찾아왔을까요? 왓슨의 수첩에 적힌 첫 번째 사건을 펼쳐 봐요."], "cards": [{"en": "Sherlock Holmes", "ko": "셜록 홈즈", "new": false, "line": "런던 베이커 가 221B에 사는 탐정이에요. 사람을 잠깐 보기만 해도 그 사람이 어디에 다녀왔는지 알아맞혀요.", "img": "img/p_holmes.jpg"}, {"en": "Watson", "ko": "왓슨", "new": false, "line": "의사이고 홈즈의 친구예요. 이 이야기를 들려주는 '나(I)'예요. 오늘 홈즈를 찾아갔다가 윌슨 씨의 이야기를 같이 들어요.", "img": "img/p_watson.jpg"}, {"en": "Jabez Wilson", "ko": "제이베즈 윌슨", "new": true, "line": "불타는 듯한 빨간 머리에, 몸집이 크고 나이 지긋한 아저씨예요. 작은 전당포를 하는데, 가게 밖에는 거의 나가지 않아요. 예전에 중국에 다녀온 적이 있어요.", "img": "img/p_wilson.jpg"}, {"en": "Vincent Spaulding", "ko": "빈센트 스폴딩", "new": true, "line": "윌슨 씨 가게의 조수예요. 아주 똑똑한데도 월급을 절반만 받아요. 사진을 좋아해서 지하실에 자주 내려가요. 윌슨 씨에게 빨간 머리 연맹 광고를 보여 준 사람이에요.", "img": "img/p_vincent.jpg"}, {"en": "Duncan Ross", "ko": "던컨 로스", "new": true, "line": "빨간 머리 연맹 사무실에 있는 작은 남자예요. 머리가 윌슨 씨보다 더 빨개요. 다른 사람은 다 떨어뜨리고 윌슨 씨만 뽑았어요.", "img": "img/p_duncanross.svg"}], "words": [{"w": "advertisement", "ko": "광고", "ex": "Spaulding showed me this advertisement.", "why": "모든 일이 이 신문 광고 한 줄에서 시작돼요.", "src": "audio/w_advertisement.mp3", "exsrc": "audio/c1_v0.mp3"}, {"w": "vacancy", "ko": "빈자리", "ex": "There is a vacancy.", "why": "연맹에 사람 한 명이 들어갈 자리가 비었다는 말이에요.", "src": "audio/w_vacancy.mp3", "exsrc": "audio/c1_v1.mp3"}, {"w": "apply", "ko": "지원하다", "ex": "All red-headed men over twenty-one can apply.", "why": "누가 그 자리에 들어가겠다고 손을 들 수 있는지 알려 줘요.", "src": "audio/w_apply.mp3", "exsrc": "audio/c1_v2.mp3"}, {"w": "pawnshop", "ko": "전당포", "ex": "I have a small pawnshop.", "why": "물건을 맡기면 돈을 빌려주는 가게예요. 윌슨 씨가 일하는 곳이라 다음 장에도 나와요.", "src": "audio/w_pawnshop.mp3", "exsrc": "audio/c1_v3.mp3"}, {"w": "assistant", "ko": "조수", "ex": "My assistant, Vincent Spaulding, is very smart.", "why": "가게 일을 돕는 사람이에요. 오늘 단서는 대부분 이 조수 이야기예요.", "src": "audio/w_assistant.mp3", "exsrc": "audio/c1_v4.mp3"}, {"w": "cellar", "ko": "지하실", "ex": "He often dives down into the cellar to develop his pictures.", "why": "스폴딩이 자주 사라지는 곳이에요. 기억해 두세요.", "src": "audio/w_cellar.mp3", "exsrc": "audio/c1_v5.mp3"}, {"w": "office", "ko": "사무실", "ex": "You must stay in the office the whole time.", "why": "윌슨 씨가 매일 네 시간씩 갇혀 있다시피 한 곳이에요.", "src": "audio/w_office.mp3", "exsrc": "audio/c1_v6.mp3"}, {"w": "copy", "ko": "베끼다", "ex": "Your work is to copy out the Encyclopaedia Britannica.", "why": "윌슨 씨가 여덟 주 동안 한 일이에요. 백과사전을 손으로 그대로 옮겨 적었어요.", "src": "audio/w_copy.mp3", "exsrc": "audio/c1_v7.mp3"}], "scenes": [{"no": 1, "title": "홈즈의 방에 온 손님", "paras": [{"kind": "p", "units": [{"t": "One autumn day, I visited Sherlock Holmes.", "sp": "Watson", "src": "audio/c1_1_00_00.mp3"}, {"t": "A stout old man with fiery red hair was with him.", "sp": "Watson", "src": "audio/c1_1_00_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"You could not have come at a better time, my dear Watson,\"", "sp": "Holmes", "src": "audio/c1_1_01_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c1_1_01_01.mp3"}, {"t": "\"This is Mr. Jabez Wilson.", "sp": "Holmes", "src": "audio/c1_1_01_02.mp3"}, {"t": "He has been in China.\"", "sp": "Holmes", "src": "audio/c1_1_01_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"How did you know that?\"", "sp": "Wilson", "src": "audio/c1_1_02_00.mp3"}, {"t": "asked Mr. Wilson.", "sp": "Watson", "src": "audio/c1_1_02_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"The fish tattoo on your wrist could only have been done in China.\"", "sp": "Holmes", "src": "audio/c1_1_03_00.mp3"}]}, {"kind": "p", "units": [{"t": "Mr. Wilson pointed to his old newspaper.", "sp": "Watson", "src": "audio/c1_1_04_00.mp3"}, {"t": "\"This is what began it all.\"", "sp": "Wilson", "src": "audio/c1_1_04_01.mp3"}]}, {"kind": "sign", "units": [{"t": "TO THE RED-HEADED LEAGUE: There is a vacancy.", "sp": "Sign", "src": "audio/c1_1_05_00.mp3"}, {"t": "A member will get £4 a week for very easy work.", "sp": "Sign", "src": "audio/c1_1_05_01.mp3"}, {"t": "All red-headed men over twenty-one can apply.", "sp": "Sign", "src": "audio/c1_1_05_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"What on earth does this mean?\"", "sp": "Watson", "src": "audio/c1_1_06_00.mp3"}, {"t": "I said.", "sp": "Watson", "src": "audio/c1_1_06_01.mp3"}]}], "check": {"q": "광고는 어떤 사람을 찾고, 뽑히면 무엇을 준다고 하나요?", "a": "21살이 넘은 빨간 머리 남자를 찾아요. 뽑히면 아주 쉬운 일을 하고 일주일에 4파운드를 받아요."}, "imgs": [{"at": 0, "src": "img/c1_a.svg"}]}, {"no": 2, "title": "월급을 반만 받는 조수", "paras": [{"kind": "p", "units": [{"t": "\"I have a small pawnshop,\"", "sp": "Wilson", "src": "audio/c1_2_00_00.mp3"}, {"t": "said Mr. Wilson.", "sp": "Watson", "src": "audio/c1_2_00_01.mp3"}, {"t": "\"My assistant, Vincent Spaulding, is very smart.", "sp": "Wilson", "src": "audio/c1_2_00_02.mp3"}, {"t": "He could earn twice as much somewhere else, but he works for half pay.\"", "sp": "Wilson", "src": "audio/c1_2_00_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"Your assistant may be as strange as your advertisement,\"", "sp": "Holmes", "src": "audio/c1_2_01_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c1_2_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"He loves photography,\"", "sp": "Wilson", "src": "audio/c1_2_02_00.mp3"}, {"t": "said Mr. Wilson.", "sp": "Watson", "src": "audio/c1_2_02_01.mp3"}, {"t": "\"He often dives down into the cellar to develop his pictures.", "sp": "Wilson", "src": "audio/c1_2_02_02.mp3"}, {"t": "He goes down like a rabbit into its hole.", "sp": "Wilson", "src": "audio/c1_2_02_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"Eight weeks ago, Spaulding showed me this advertisement.", "sp": "Wilson", "src": "audio/c1_2_03_00.mp3"}, {"t": "'I wish I was a red-headed man,'", "sp": "Spaulding", "src": "audio/c1_2_03_01.mp3"}, {"t": "he said.", "sp": "Wilson", "src": "audio/c1_2_03_02.mp3"}, {"t": "I hardly ever leave my shop, so I didn't know about the League.", "sp": "Wilson", "src": "audio/c1_2_03_03.mp3"}, {"t": "But my hair is very red.", "sp": "Wilson", "src": "audio/c1_2_03_04.mp3"}, {"t": "So I closed the shop.", "sp": "Wilson", "src": "audio/c1_2_03_05.mp3"}, {"t": "We went together.", "sp": "Wilson", "src": "audio/c1_2_03_06.mp3"}]}], "check": {"q": "조수 스폴딩에게 이상한 점은 뭘까요?", "a": "다른 데서 두 배를 벌 수 있을 만큼 똑똑한데, 월급을 반만 받고 일해요. 사진을 현상한다며 지하실에도 자주 내려가고요."}, "imgs": []}, {"no": 3, "title": "빨간 머리로 꽉 찬 거리", "paras": [{"kind": "p", "units": [{"t": "\"The street was full of red-headed men.", "sp": "Wilson", "src": "audio/c1_3_00_00.mp3"}, {"t": "Spaulding pushed me through the crowd into the office.", "sp": "Wilson", "src": "audio/c1_3_00_01.mp3"}, {"t": "A small man with even redder hair sat there.", "sp": "Wilson", "src": "audio/c1_3_00_02.mp3"}, {"t": "He found something wrong with every man.", "sp": "Wilson", "src": "audio/c1_3_00_03.mp3"}, {"t": "But when he saw me, he closed the door.", "sp": "Wilson", "src": "audio/c1_3_00_04.mp3"}]}, {"kind": "p", "units": [{"t": "\"'This man is perfect!'", "sp": "Ross", "src": "audio/c1_3_01_00.mp3"}, {"t": "he said.", "sp": "Wilson", "src": "audio/c1_3_01_01.mp3"}, {"t": "Then he pulled my hair hard.", "sp": "Wilson", "src": "audio/c1_3_01_02.mp3"}, {"t": "'It is real,'", "sp": "Ross", "src": "audio/c1_3_01_03.mp3"}, {"t": "he said.", "sp": "Wilson", "src": "audio/c1_3_01_04.mp3"}, {"t": "'Some men have tried wigs.'", "sp": "Ross", "src": "audio/c1_3_01_05.mp3"}]}, {"kind": "p", "units": [{"t": "\"'My name is Mr. Duncan Ross,'", "sp": "Ross", "src": "audio/c1_3_02_00.mp3"}, {"t": "he said.", "sp": "Wilson", "src": "audio/c1_3_02_01.mp3"}]}], "check": {"q": "던컨 로스는 왜 윌슨 씨의 머리카락을 세게 잡아당겼을까요?", "a": "가발이 아니라 진짜 빨간 머리인지 확인하려고요. 가발을 쓰고 온 사람들이 있었대요."}, "imgs": [{"at": 0, "src": "img/c1_b.svg"}, {"at": 1, "src": "img/c1_c.svg"}]}, {"no": 4, "title": "백과사전을 베끼는 일", "paras": [{"kind": "p", "units": [{"t": "\"'But I have a shop,'", "sp": "Wilson", "src": "audio/c1_4_00_00.mp3"}, {"t": "I said.", "sp": "Watson", "src": "audio/c1_4_00_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"'Never mind, Mr. Wilson,'", "sp": "Spaulding", "src": "audio/c1_4_01_00.mp3"}, {"t": "said Spaulding.", "sp": "Wilson", "src": "audio/c1_4_01_01.mp3"}, {"t": "'I should be able to look after that for you.'", "sp": "Spaulding", "src": "audio/c1_4_01_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"'The hours are ten to two,'", "sp": "Ross", "src": "audio/c1_4_02_00.mp3"}, {"t": "said Mr. Ross.", "sp": "Wilson", "src": "audio/c1_4_02_01.mp3"}, {"t": "'You must stay in the office the whole time.", "sp": "Ross", "src": "audio/c1_4_02_02.mp3"}, {"t": "If you leave, you lose the job forever.", "sp": "Ross", "src": "audio/c1_4_02_03.mp3"}, {"t": "Your work is to copy out the Encyclopaedia Britannica.'", "sp": "Ross", "src": "audio/c1_4_02_04.mp3"}]}, {"kind": "p", "units": [{"t": "\"Every day, I sat in that office and copied.", "sp": "Wilson", "src": "audio/c1_4_03_00.mp3"}, {"t": "Every Saturday, Mr. Ross gave me four gold coins.", "sp": "Wilson", "src": "audio/c1_4_03_01.mp3"}, {"t": "After a while, he stopped coming in.", "sp": "Wilson", "src": "audio/c1_4_03_02.mp3"}, {"t": "But I never left the room.", "sp": "Wilson", "src": "audio/c1_4_03_03.mp3"}, {"t": "For eight weeks, I wrote about Abbots, Archery and Armour.", "sp": "Wilson", "src": "audio/c1_4_03_04.mp3"}]}, {"kind": "p", "units": [{"t": "\"And then, suddenly, the whole business came to an end.\"", "sp": "Wilson", "src": "audio/c1_4_04_00.mp3"}]}], "check": {"q": "윌슨 씨가 꼭 지켜야 했던 규칙은 뭐였나요?", "a": "10시부터 2시까지 사무실을 절대 떠나면 안 됐어요. 떠나면 일자리를 영영 잃어요. 그래서 로스가 오지 않게 된 뒤에도 윌슨 씨는 한 번도 방을 나가지 않았어요."}, "imgs": [{"at": 0, "src": "img/d4_a.jpg"}]}], "solve": null, "solve_answers": [], "clues": [{"ko": "스폴딩은 두 배를 벌 수 있는데도 월급을 반만 받고, 지하실에 자주 내려가요.", "en": "Spaulding works for half pay. He often goes down into the cellar."}, {"ko": "윌슨 씨에게 광고를 보여 준 것도, \"가게는 제가 봐 드릴 수 있어요\"라고 한 것도 스폴딩이에요.", "en": "Spaulding showed Mr. Wilson the advertisement. He also said, \"I should be able to look after that for you.\""}, {"ko": "윌슨 씨는 매일 10시부터 2시까지 사무실을 한 번도 떠나지 않아요. 원래 가게 밖에도 거의 나가지 않는 사람이에요.", "en": "Mr. Wilson never leaves the office from ten to two. He hardly ever leaves his shop."}], "clue_intro": "오늘 읽은 내용에서 이 세 가지를 수첩에 적어 두세요. 아직 무슨 뜻인지 몰라도 괜찮아요.", "quiz": [{"q": "What are the hours of Mr. Wilson's new job?", "ko": "윌슨 씨의 새 일은 몇 시부터 몇 시까지인가요?", "opts": ["① nine to five", "② two to ten", "③ ten to two", "④ all day"], "answer": "③", "why": "던컨 로스가 \"The hours are ten to two.\"라고 말해요. 오전 10시부터 오후 2시까지, 하루 네 시간이에요."}, {"q": "Why did Mr. Ross pull Mr. Wilson's hair?", "ko": "던컨 로스는 왜 윌슨 씨의 머리카락을 잡아당겼나요?", "opts": ["① He wanted to check that it was real.", "② He was angry.", "③ He wanted to cut it.", "④ It was a game."], "answer": "①", "why": "잡아당긴 다음 던컨 로스가 \"'It is real,' he said. 'Some men have tried wigs.'\"라고 말해요. 가발이 아닌지 확인한 거예요."}, {"q": "Why does Holmes say, \"Your assistant may be as strange as your advertisement\"?", "ko": "홈즈는 왜 조수도 광고만큼 이상하다고 했을까요?", "opts": ["① Spaulding has red hair.", "② Spaulding is a bad worker.", "③ Spaulding wrote the advertisement.", "④ Spaulding is smart, but he works for half pay."], "answer": "④", "why": "바로 앞에서 윌슨 씨가 \"He could earn twice as much somewhere else, but he works for half pay.\"라고 말했어요. 두 배를 벌 수 있는 사람이 반만 받고 일하니 이상하다고 본 거예요. ①은 본문에 없는 내용이에요. 스폴딩은 오히려 \"I wish I was a red-headed man.\"이라고 했어요. ③도 오늘 글에는 나오지 않아요."}, {"q": "\"Your work is to copy out the Encyclopaedia Britannica.\" What does copy mean here?", "ko": "여기서 copy는 무슨 뜻일까요?", "opts": ["① to take a picture", "② to sell something", "③ to write the same words again", "④ to read quietly"], "answer": "③", "why": "바로 뒤에 \"I sat in that office and copied.\"와 \"I wrote about Abbots, Archery and Armour.\"가 이어져요. 백과사전에 있는 글을 그대로 옮겨 적는 일이에요."}], "record": [{"t": "You could not have come at a better time, my dear Watson.", "src": "audio/c1_r0.mp3", "sp": "Holmes"}, {"t": "This is what began it all.", "src": "audio/c1_r1.mp3", "sp": "Wilson"}, {"t": "And then, suddenly, the whole business came to an end.", "src": "audio/c1_r2.mp3", "sp": "Wilson"}], "think": "", "reflect": null, "cert": null, "end": null, "words_read": 400}, "2": {"n": 2, "label": "2장", "title_en": "The League Is Gone", "title_ko": "사라진 연맹", "new_text": false, "source": "원작: 아서 코난 도일, 「빨간 머리 연맹(The Red-Headed League)」, 『셜록 홈즈의 모험』(Project Gutenberg #1661, 1562~1797행). 초6 눈높이(CEFR A2~B1 초반)로 쉽게 고쳐 쓴 글이에요.", "recap_title": "지난 이야기", "recap": ["윌슨 씨는 조수 스폴딩이 보여 준 광고를 보고 빨간 머리 연맹에 뽑혔어요. 그 뒤 여덟 주 동안 매일 10시부터 2시까지 사무실에서 백과사전을 베꼈어요. 그런데 그 일이 갑자기 끝나 버렸대요."], "cards": [{"en": "Sherlock Holmes", "ko": "셜록 홈즈", "new": false, "line": "런던 베이커 가 221B에 사는 탐정이에요. 윌슨 씨의 이야기를 듣고 사건을 맡았어요.", "img": "img/p_holmes.jpg"}, {"en": "Watson", "ko": "왓슨", "new": false, "line": "의사이고 홈즈의 친구예요. 이 이야기를 들려주는 '나(I)'예요. 오늘은 홈즈를 따라 윌슨 씨 가게에 가요.", "img": "img/p_watson.jpg"}, {"en": "Jabez Wilson", "ko": "제이베즈 윌슨", "new": false, "line": "빨간 머리의 전당포 주인이에요. 여덟 주 동안 연맹 사무실에서 백과사전을 베꼈어요. 홈즈에게 연맹이 갑자기 끝난 이야기를 들려줘요.", "img": "img/p_wilson.jpg"}, {"en": "Vincent Spaulding", "ko": "빈센트 스폴딩", "new": false, "line": "윌슨 씨 가게의 조수예요. 윌슨 씨에게 광고를 보여 줬고, 윌슨 씨가 사무실에 있는 동안 가게를 봐 주겠다고 했어요. 몸집이 작고 행동이 아주 빨라요. 서른은 넘었는데 얼굴에 수염이 없고, 이마에 하얀 자국이 있어요.", "img": "img/p_vincent.jpg"}, {"en": "Duncan Ross", "ko": "던컨 로스", "new": false, "line": "빨간 머리 연맹 사무실에 있던 작은 남자예요. 윌슨 씨를 뽑았어요. 그런데 건물 주인은 이 이름을 처음 듣는대요.", "img": "img/p_duncanross.svg"}], "words": [{"w": "dissolve", "ko": "(모임을) 없애다, 해산하다", "ex": "THE RED-HEADED LEAGUE IS DISSOLVED.", "why": "사무실 문에 붙은 쪽지의 말이에요. 연맹이 하루아침에 없어졌다는 뜻이에요.", "src": "audio/w_dissolve.mp3", "exsrc": "audio/c2_v0.mp3"}, {"w": "landlord", "ko": "건물 주인", "ex": "I went to the landlord.", "why": "연맹 사무실이 있던 건물의 주인이에요. 던컨 로스를 모른다고 했어요.", "src": "audio/w_landlord.mp3", "exsrc": "audio/c2_v1.mp3"}, {"w": "address", "ko": "주소", "ex": "He gave me a new address.", "why": "로스가 남긴 새 주소에는 그를 아는 사람이 없었어요.", "src": "audio/w_address.mp3", "exsrc": "audio/c2_v2.mp3"}, {"w": "forehead", "ko": "이마", "ex": "He has a white mark from acid on his forehead.", "why": "스폴딩을 알아볼 수 있는 표시예요.", "src": "audio/w_forehead.mp3", "exsrc": "audio/c2_v3.mp3"}, {"w": "pavement", "ko": "보도, 길바닥", "ex": "Then he hit the pavement hard with his stick.", "why": "홈즈가 지팡이로 두드린 곳이에요. 왜 두드렸는지 기억해 두세요.", "src": "audio/w_pavement.mp3", "exsrc": "audio/c2_v4.mp3"}, {"w": "knee", "ko": "무릎", "ex": "The knees of his trousers.", "why": "홈즈가 조수의 얼굴이 아니라 무릎을 봤어요.", "src": "audio/w_knee.mp3", "exsrc": "audio/c2_v5.mp3"}, {"w": "corner", "ko": "모퉁이", "ex": "We walked round the corner.", "why": "모퉁이를 돌아가면 윌슨 씨 가게 뒤쪽 큰길이 나와요.", "src": "audio/w_corner.mp3", "exsrc": "audio/c2_v6.mp3"}], "scenes": [{"no": 1, "title": "문에 붙은 쪽지", "paras": [{"kind": "p", "units": [{"t": "\"To an end?\"", "sp": "Holmes", "src": "audio/c2_1_00_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c2_1_00_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Yes.", "sp": "Wilson", "src": "audio/c2_1_01_00.mp3"}, {"t": "This morning, the door was locked.", "sp": "Wilson", "src": "audio/c2_1_01_01.mp3"}, {"t": "This card was on it.\"", "sp": "Wilson", "src": "audio/c2_1_01_02.mp3"}]}, {"kind": "sign", "units": [{"t": "THE RED-HEADED LEAGUE IS DISSOLVED.", "sp": "Sign", "src": "audio/c2_1_02_00.mp3"}]}, {"kind": "p", "units": [{"t": "Holmes and I looked at the card and Mr. Wilson's sad face.", "sp": "Watson", "src": "audio/c2_1_03_00.mp3"}, {"t": "We both burst out laughing.", "sp": "Watson", "src": "audio/c2_1_03_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"It is not funny!\"", "sp": "Wilson", "src": "audio/c2_1_04_00.mp3"}, {"t": "cried Mr. Wilson.", "sp": "Watson", "src": "audio/c2_1_04_01.mp3"}, {"t": "His face went red.", "sp": "Watson", "src": "audio/c2_1_04_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"No, no,\"", "sp": "Holmes", "src": "audio/c2_1_05_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c2_1_05_01.mp3"}, {"t": "\"Please sit down.", "sp": "Holmes", "src": "audio/c2_1_05_02.mp3"}, {"t": "What did you do next?\"", "sp": "Holmes", "src": "audio/c2_1_05_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"I went to the landlord.", "sp": "Wilson", "src": "audio/c2_1_06_00.mp3"}, {"t": "He had never heard of the League.", "sp": "Wilson", "src": "audio/c2_1_06_01.mp3"}, {"t": "He did not know Mr. Duncan Ross, either.", "sp": "Wilson", "src": "audio/c2_1_06_02.mp3"}, {"t": "'The red-headed man?'", "sp": "Landlord", "src": "audio/c2_1_06_03.mp3"}, {"t": "he said.", "sp": "Wilson", "src": "audio/c2_1_06_04.mp3"}, {"t": "'His name was William Morris.", "sp": "Landlord", "src": "audio/c2_1_06_05.mp3"}, {"t": "He moved out yesterday.'", "sp": "Landlord", "src": "audio/c2_1_06_06.mp3"}, {"t": "He gave me a new address.", "sp": "Wilson", "src": "audio/c2_1_06_07.mp3"}, {"t": "But it was a factory.", "sp": "Wilson", "src": "audio/c2_1_06_08.mp3"}, {"t": "Nobody there knew Mr. Morris or Mr. Ross.\"", "sp": "Wilson", "src": "audio/c2_1_06_09.mp3"}]}], "check": {"q": "건물 주인은 던컨 로스에 대해 뭐라고 했나요?", "a": "그런 이름은 모른대요. 빨간 머리 남자는 윌리엄 모리스이고 어제 이사 갔다고 했어요. 그런데 그가 남긴 새 주소에 가 보니 공장이었고, 두 이름을 아는 사람이 아무도 없었어요."}, "imgs": [{"at": 0, "src": "img/d4_b.jpg"}]}, {"no": 2, "title": "조수는 어떤 사람?", "paras": [{"kind": "p", "units": [{"t": "\"First, a few questions,\"", "sp": "Holmes", "src": "audio/c2_2_00_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c2_2_00_01.mp3"}, {"t": "\"Your assistant showed you the advertisement.", "sp": "Holmes", "src": "audio/c2_2_00_02.mp3"}, {"t": "How long had he been with you then?\"", "sp": "Holmes", "src": "audio/c2_2_00_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"About a month.\"", "sp": "Wilson", "src": "audio/c2_2_01_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"Why did you choose him?\"", "sp": "Holmes", "src": "audio/c2_2_02_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"Because he would come cheap.\"", "sp": "Wilson", "src": "audio/c2_2_03_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"For half pay, in fact.\"", "sp": "Holmes", "src": "audio/c2_2_04_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"Yes.\"", "sp": "Wilson", "src": "audio/c2_2_05_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"What is Vincent Spaulding like?\"", "sp": "Holmes", "src": "audio/c2_2_06_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"He is small and very quick.", "sp": "Wilson", "src": "audio/c2_2_07_00.mp3"}, {"t": "He is at least thirty, but he has no hair on his face.", "sp": "Wilson", "src": "audio/c2_2_07_01.mp3"}, {"t": "He has a white mark from acid on his forehead.\"", "sp": "Wilson", "src": "audio/c2_2_07_02.mp3"}]}, {"kind": "p", "units": [{"t": "Holmes sat up in his chair.", "sp": "Watson", "src": "audio/c2_2_08_00.mp3"}, {"t": "\"I thought so,\"", "sp": "Holmes", "src": "audio/c2_2_08_01.mp3"}, {"t": "he said.", "sp": "Wilson", "src": "audio/c2_2_08_02.mp3"}, {"t": "\"Does he have holes in his ears for earrings?\"", "sp": "Holmes", "src": "audio/c2_2_08_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"Yes, sir.\"", "sp": "Wilson", "src": "audio/c2_2_09_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"Today is Saturday,\"", "sp": "Holmes", "src": "audio/c2_2_10_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c2_2_10_01.mp3"}, {"t": "\"By Monday, I hope to have an answer.\"", "sp": "Holmes", "src": "audio/c2_2_10_02.mp3"}]}], "check": {"q": "스폴딩이 어떻게 생겼는지 듣고 홈즈는 어떻게 했나요?", "a": "의자에서 몸을 일으켜 앉으며 \"그럴 줄 알았어요\"라고 했어요. 그리고 귀에 귀걸이 구멍이 있는지 물었어요."}, "imgs": []}, {"no": 3, "title": "얼굴이 아니라 무릎", "paras": [{"kind": "p", "units": [{"t": "Later that day, Holmes and I went to Mr. Wilson's shop in a quiet little square.", "sp": "Watson", "src": "audio/c2_3_00_00.mp3"}, {"t": "Holmes looked carefully at the houses.", "sp": "Watson", "src": "audio/c2_3_00_01.mp3"}, {"t": "Then he hit the pavement hard with his stick, two or three times.", "sp": "Watson", "src": "audio/c2_3_00_02.mp3"}, {"t": "He knocked on the door.", "sp": "Watson", "src": "audio/c2_3_00_03.mp3"}, {"t": "A young man with no beard opened it.", "sp": "Watson", "src": "audio/c2_3_00_04.mp3"}]}, {"kind": "p", "units": [{"t": "\"How do I get to the Strand?\"", "sp": "Holmes", "src": "audio/c2_3_01_00.mp3"}, {"t": "asked Holmes.", "sp": "Watson", "src": "audio/c2_3_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Third right, fourth left,\"", "sp": "Spaulding", "src": "audio/c2_3_02_00.mp3"}, {"t": "said the assistant quickly.", "sp": "Watson", "src": "audio/c2_3_02_01.mp3"}, {"t": "He closed the door.", "sp": "Watson", "src": "audio/c2_3_02_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"Smart fellow,\"", "sp": "Holmes", "src": "audio/c2_3_03_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c2_3_03_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"You asked the way only to see him,\"", "sp": "Watson", "src": "audio/c2_3_04_00.mp3"}, {"t": "I said.", "sp": "Watson", "src": "audio/c2_3_04_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Not him.", "sp": "Holmes", "src": "audio/c2_3_05_00.mp3"}, {"t": "The knees of his trousers.\"", "sp": "Holmes", "src": "audio/c2_3_05_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"And what did you see?\"", "sp": "Watson", "src": "audio/c2_3_06_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"What I expected to see.\"", "sp": "Holmes", "src": "audio/c2_3_07_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"Why did you hit the pavement?\"", "sp": "Watson", "src": "audio/c2_3_08_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"This is a time for looking, Doctor, not for talking.\"", "sp": "Holmes", "src": "audio/c2_3_09_00.mp3"}]}], "check": {"q": "홈즈는 문을 연 조수에게서 무엇을 보려고 길을 물었나요?", "a": "얼굴이 아니라 바지 무릎이요. 왓슨이 \"그 사람을 보려고 길을 물었지요?\"라고 하자 홈즈는 \"그 사람 말고, 바지 무릎\"이라고 했어요."}, "imgs": [{"at": 0, "src": "img/d4_c.jpg"}]}, {"no": 4, "title": "광장 뒤의 큰길", "paras": [{"kind": "p", "units": [{"t": "We walked round the corner.", "sp": "Watson", "src": "audio/c2_4_00_00.mp3"}, {"t": "Behind the square was a big, busy road.", "sp": "Watson", "src": "audio/c2_4_00_01.mp3"}, {"t": "It had a line of fine shops.", "sp": "Watson", "src": "audio/c2_4_00_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"Let me remember the order of the shops,\"", "sp": "Holmes", "src": "audio/c2_4_01_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c2_4_01_01.mp3"}, {"t": "\"I like to know London well.", "sp": "Holmes", "src": "audio/c2_4_01_02.mp3"}, {"t": "There is a little newspaper shop, the City and Suburban Bank, and a restaurant.", "sp": "Holmes", "src": "audio/c2_4_01_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"Now, Doctor, our work is done.", "sp": "Holmes", "src": "audio/c2_4_02_00.mp3"}, {"t": "Let's go to the concert.\"", "sp": "Holmes", "src": "audio/c2_4_02_01.mp3"}]}], "check": {"q": "광장 뒤 큰길에서 홈즈는 무엇을 했나요?", "a": "가게들이 늘어선 순서를 외웠어요. 작은 신문 가게, 시티 앤드 서버번 은행, 식당 순서예요. 그러고는 이제 할 일은 다 했으니 음악회에 가자고 했어요."}, "imgs": [{"at": 0, "src": "img/d4_d.jpg"}]}], "solve": null, "solve_answers": [], "clues": [{"ko": "스폴딩은 서른은 넘었는데 얼굴에 수염이 없고, 이마에 산(약품)이 튀어 생긴 하얀 자국이 있고, 귀에 귀걸이 구멍이 있어요. 이 말을 듣고 홈즈는 \"그럴 줄 알았어요\"라고 했어요.", "en": "Spaulding has no hair on his face, a white mark on his forehead and holes in his ears. Holmes said, \"I thought so.\""}, {"ko": "홈즈는 가게 앞 길바닥을 지팡이로 두드렸어요. 그리고 문을 연 조수의 얼굴이 아니라 바지 무릎을 봤어요.", "en": "Holmes hit the pavement with his stick. He looked at the knees of the assistant's trousers."}, {"ko": "윌슨 씨 가게가 있는 광장 바로 뒤 큰길에 시티 앤드 서버번 은행이 있어요.", "en": "The City and Suburban Bank is on the busy road behind Mr. Wilson's square."}], "clue_intro": "오늘 읽은 내용에서 이 세 가지를 수첩에 적어 두세요.", "quiz": [{"q": "What did the landlord say about the red-headed man?", "ko": "건물 주인은 빨간 머리 남자에 대해 뭐라고 했나요?", "opts": ["① His name was Duncan Ross.", "② He was Mr. Wilson's assistant.", "③ He worked at the bank.", "④ His name was William Morris."], "answer": "④", "why": "건물 주인이 \"'His name was William Morris. He moved out yesterday.'\"라고 말해요. 던컨 로스라는 이름은 들어 본 적도 없대요(He did not know Mr. Duncan Ross, either). 그래서 ①은 틀려요."}, {"q": "How long had Spaulding been with Mr. Wilson when he showed him the advertisement?", "ko": "스폴딩이 윌슨 씨에게 광고를 보여 줬을 때, 가게에서 일한 지 얼마나 됐었나요?", "opts": ["① about a month", "② one week", "③ eight weeks", "④ about a year"], "answer": "①", "why": "홈즈가 \"How long had he been with you then?\"이라고 묻자 윌슨 씨가 \"About a month.\"라고 답해요. ③ 여덟 주는 윌슨 씨가 백과사전을 베낀 기간이에요."}, {"q": "Why did Holmes ask the assistant the way to the Strand?", "ko": "홈즈는 왜 조수에게 스트랜드 거리로 가는 길을 물었을까요?", "opts": ["① He was lost.", "② He wanted to buy something in the shop.", "③ He wanted to see the knees of the assistant's trousers.", "④ He wanted to talk to Mr. Wilson."], "answer": "③", "why": "왓슨이 \"You asked the way only to see him.\"이라고 하자 홈즈가 \"Not him. The knees of his trousers.\"라고 답해요. 길을 몰라서 물은 게 아니라 무릎을 보려고 물은 거예요."}, {"q": "\"Then he hit the pavement hard with his stick.\" What is a pavement?", "ko": "여기서 pavement는 무엇일까요?", "opts": ["① the door of a shop", "② the ground where people walk next to a road", "③ a long stick", "④ a room under a house"], "answer": "②", "why": "홈즈는 가게 문을 두드리기 전에, 가게 앞에 서서 지팡이로 pavement를 두드렸어요. 사람이 걸어 다니는 길바닥이에요. 문은 그다음에 따로 두드려요(He knocked on the door). ④ 집 아래 방은 cellar(지하실)예요."}], "record": [{"t": "It is not funny!", "src": "audio/c2_r0.mp3", "sp": "Wilson"}, {"t": "Third right, fourth left.", "src": "audio/c2_r1.mp3", "sp": "Spaulding"}, {"t": "This is a time for looking, Doctor, not for talking.", "src": "audio/c2_r2.mp3", "sp": "Holmes"}], "think": "", "reflect": null, "cert": null, "end": null, "words_read": 400}, "3": {"n": 3, "label": "3장", "title_en": "Waiting in the Dark", "title_ko": "어둠 속에서 기다리기", "new_text": false, "source": "원작: 아서 코난 도일, 「빨간 머리 연맹(The Red-Headed League)」, 『셜록 홈즈의 모험』(Project Gutenberg #1661, 1821~2152행). 초6 눈높이(CEFR A2~B1 초반)로 쉽게 고쳐 쓴 글이에요.", "recap_title": "지난 이야기", "recap": ["빨간 머리 연맹은 하루아침에 사라졌어요. 건물 주인은 던컨 로스를 몰랐고, 새 주소에 가 보니 아무도 그를 몰랐어요. 홈즈는 윌슨 씨 가게 앞 길바닥을 지팡이로 두드리고, 문을 연 조수의 바지 무릎을 봤어요. 그리고 가게가 있는 광장 바로 뒤 큰길에서 가게 순서를 외웠어요."], "cards": [{"en": "Sherlock Holmes", "ko": "셜록 홈즈", "new": false, "line": "런던 베이커 가 221B에 사는 탐정이에요. 오늘 밤 큰 범죄를 막으려고 해요.", "img": "img/p_holmes.jpg"}, {"en": "Watson", "ko": "왓슨", "new": false, "line": "의사이고 홈즈의 친구예요. 이 이야기를 들려주는 '나(I)'예요. 오늘 밤 홈즈를 돕기로 했어요.", "img": "img/p_watson.jpg"}, {"en": "Mr. Jones", "ko": "존스", "new": true, "line": "경찰 형사예요. 존 클레이라는 도둑을 몇 년째 쫓고 있어요.", "img": "img/p_jones.svg"}, {"en": "Mr. Merryweather", "ko": "메리웨더", "new": true, "line": "은행에서 온 사람이에요. 시무룩한 얼굴이에요.", "img": "img/p_merryweather.jpg"}, {"en": "John Clay", "ko": "존 클레이", "new": true, "line": "존스가 쫓는 도둑이에요. 젊지만 아주 영리해요. 존스는 아직 그 얼굴을 한 번도 본 적이 없어요.", "img": "img/p_unknown.svg"}], "words": [{"w": "crime", "ko": "범죄", "ex": "A big crime is planned, Doctor.", "why": "홈즈가 오늘 밤 막으려는 일이에요.", "src": "audio/w_crime.mp3", "exsrc": "audio/c3_v0.mp3"}, {"w": "thief", "ko": "도둑", "ex": "He is young, but he is a very clever thief.", "why": "존스가 몇 년째 쫓는 존 클레이를 설명하는 말이에요.", "src": "audio/w_thief.mp3", "exsrc": "audio/c3_v1.mp3"}, {"w": "hollow", "ko": "속이 빈", "ex": "Dear me! It sounds hollow!", "why": "금고 바닥 밑이 비어 있다는 소리예요. 큰 단서예요.", "src": "audio/w_hollow.mp3", "exsrc": "audio/c3_v2.mp3"}, {"w": "lantern", "ko": "손에 드는 등불", "ex": "Holmes covered his lantern.", "why": "등불을 가리자 금고가 깜깜해져요.", "src": "audio/w_lantern.mp3", "exsrc": "audio/c3_v3.mp3"}, {"w": "crack", "ko": "틈", "ex": "With a lantern and a lens, he looked at the cracks between the stones.", "why": "홈즈가 살펴본 곳이자, 나중에 불빛이 새어 나온 곳이에요.", "src": "audio/w_crack.mp3", "exsrc": "audio/c3_v4.mp3"}, {"w": "silent", "ko": "조용한", "ex": "Now we must be silent and wait.", "why": "어둠 속에서 숨죽이고 기다리는 장면이에요.", "src": "audio/w_silent.mp3", "exsrc": "audio/c3_v5.mp3"}, {"w": "flash", "ko": "번쩍 비추다", "ex": "When they come, I will flash a light.", "why": "홈즈가 신호를 보내는 방법이에요.", "src": "audio/w_flash.mp3", "exsrc": "audio/c3_v6.mp3"}], "scenes": [{"no": 1, "title": "오늘 밤 열 시", "paras": [{"kind": "p", "units": [{"t": "After the concert, Holmes said,", "sp": "Watson", "src": "audio/c3_1_00_00.mp3"}, {"t": "\"A big crime is planned, Doctor.", "sp": "Holmes", "src": "audio/c3_1_00_01.mp3"}, {"t": "I need your help tonight.\"", "sp": "Holmes", "src": "audio/c3_1_00_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"I will come to Baker Street at ten,\"", "sp": "Watson", "src": "audio/c3_1_01_00.mp3"}, {"t": "I said.", "sp": "Watson", "src": "audio/c3_1_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "At ten, two men were with Holmes.", "sp": "Watson", "src": "audio/c3_1_02_00.mp3"}, {"t": "One was Mr. Jones, a police detective.", "sp": "Watson", "src": "audio/c3_1_02_01.mp3"}, {"t": "The other was Mr. Merryweather, a sad-looking man from a bank.", "sp": "Watson", "src": "audio/c3_1_02_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"Tonight, Jones, you may catch the man you want,\"", "sp": "Holmes", "src": "audio/c3_1_03_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c3_1_03_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"John Clay,\"", "sp": "Jones", "src": "audio/c3_1_04_00.mp3"}, {"t": "said Jones.", "sp": "Watson", "src": "audio/c3_1_04_01.mp3"}, {"t": "\"He is young, but he is a very clever thief.", "sp": "Jones", "src": "audio/c3_1_04_02.mp3"}, {"t": "I have followed him for years, but I have never seen his face.\"", "sp": "Jones", "src": "audio/c3_1_04_03.mp3"}]}], "check": {"q": "존스가 쫓는 존 클레이는 어떤 사람인가요?", "a": "젊지만 아주 영리한 도둑이에요. 존스가 몇 년째 쫓고 있는데, 아직 얼굴을 한 번도 못 봤대요."}, "imgs": []}, {"no": 2, "title": "은행 지하 금고", "paras": [{"kind": "p", "units": [{"t": "Mr. Merryweather led us down into a huge cellar full of boxes.", "sp": "Watson", "src": "audio/c3_2_00_00.mp3"}]}, {"kind": "p", "units": [{"t": "Mr. Merryweather hit the stone floor with his stick.", "sp": "Watson", "src": "audio/c3_2_01_00.mp3"}, {"t": "\"Dear me!", "sp": "Merryweather", "src": "audio/c3_2_01_01.mp3"}, {"t": "It sounds hollow!\"", "sp": "Merryweather", "src": "audio/c3_2_01_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"Please be quiet!\"", "sp": "Holmes", "src": "audio/c3_2_02_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c3_2_02_01.mp3"}, {"t": "He got down on his knees.", "sp": "Watson", "src": "audio/c3_2_02_02.mp3"}, {"t": "With a lantern and a lens, he looked at the cracks between the stones.", "sp": "Watson", "src": "audio/c3_2_02_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"We are in the cellar of a bank,\"", "sp": "Holmes", "src": "audio/c3_2_03_00.mp3"}, {"t": "he said.", "sp": "Watson", "src": "audio/c3_2_03_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Our French gold is here,\"", "sp": "Merryweather", "src": "audio/c3_2_04_00.mp3"}, {"t": "whispered Mr. Merryweather.", "sp": "Watson", "src": "audio/c3_2_04_01.mp3"}, {"t": "\"We have thirty thousand gold coins.\"", "sp": "Merryweather", "src": "audio/c3_2_04_02.mp3"}]}], "check": {"q": "메리웨더 씨가 지팡이로 바닥을 쳤을 때 무슨 일이 있었나요?", "a": "속이 빈 것 같은 소리가 났어요. 홈즈는 조용히 하라고 한 뒤, 무릎을 꿇고 돌 틈을 꼼꼼히 살펴봤어요."}, "imgs": [{"at": 0, "src": "img/d5_a.jpg"}]}, {"no": 3, "title": "어둠 속에서", "paras": [{"kind": "p", "units": [{"t": "\"Now we must sit in the dark,\"", "sp": "Holmes", "src": "audio/c3_3_00_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c3_3_00_01.mp3"}, {"t": "\"When they come, I will flash a light.", "sp": "Holmes", "src": "audio/c3_3_00_02.mp3"}, {"t": "Then move in fast.\"", "sp": "Holmes", "src": "audio/c3_3_00_03.mp3"}]}, {"kind": "p", "units": [{"t": "We hid behind the boxes.", "sp": "Watson", "src": "audio/c3_3_01_00.mp3"}, {"t": "Holmes covered his lantern.", "sp": "Watson", "src": "audio/c3_3_01_01.mp3"}, {"t": "It was completely dark.", "sp": "Watson", "src": "audio/c3_3_01_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"Now we must be silent and wait.\"", "sp": "Holmes", "src": "audio/c3_3_02_00.mp3"}]}, {"kind": "p", "units": [{"t": "What a long time it seemed!", "sp": "Watson", "src": "audio/c3_3_03_00.mp3"}, {"t": "I could hear the others breathing.", "sp": "Watson", "src": "audio/c3_3_03_01.mp3"}]}], "check": {"q": "홈즈는 왜 불을 가리고 상자 뒤에 숨었을까요?", "a": "누군가 오기를 기다리는 거예요. 그들이 오면 홈즈가 불을 비추는 순간 다 같이 덮치려는 거예요."}, "imgs": []}, {"no": 4, "title": "바닥에서 나온 손", "paras": [{"kind": "p", "units": [{"t": "Suddenly, I saw a light between the stones.", "sp": "Watson", "src": "audio/c3_4_00_00.mp3"}, {"t": "A white hand came up out of the floor.", "sp": "Watson", "src": "audio/c3_4_00_01.mp3"}, {"t": "Then a big stone turned over.", "sp": "Watson", "src": "audio/c3_4_00_02.mp3"}, {"t": "A young man with a boyish face climbed out.", "sp": "Watson", "src": "audio/c3_4_00_03.mp3"}, {"t": "He pulled up a friend with very red hair.", "sp": "Watson", "src": "audio/c3_4_00_04.mp3"}]}, {"kind": "p", "units": [{"t": "\"It's all clear,\"", "sp": "Clay", "src": "audio/c3_4_01_00.mp3"}, {"t": "he whispered.", "sp": "Watson", "src": "audio/c3_4_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "Holmes jumped out and caught him by the collar.", "sp": "Watson", "src": "audio/c3_4_02_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"Jump, Archie, jump!\"", "sp": "Clay", "src": "audio/c3_4_03_00.mp3"}, {"t": "cried the young man.", "sp": "Watson", "src": "audio/c3_4_03_01.mp3"}, {"t": "The red-headed man dived back down the hole.", "sp": "Watson", "src": "audio/c3_4_03_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"It's no use, John Clay,\"", "sp": "Holmes", "src": "audio/c3_4_04_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c3_4_04_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"My friend is safe,\"", "sp": "Clay", "src": "audio/c3_4_05_00.mp3"}, {"t": "said Clay coolly.", "sp": "Watson", "src": "audio/c3_4_05_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"There are three men waiting for him at the door.\"", "sp": "Holmes", "src": "audio/c3_4_06_00.mp3"}]}, {"kind": "p", "units": [{"t": "Later, Holmes explained.", "sp": "Watson", "src": "audio/c3_4_07_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"The League was a trick to get Mr. Wilson out of his shop.", "sp": "Holmes", "src": "audio/c3_4_08_00.mp3"}, {"t": "The assistant came for half pay, so he wanted that job badly.", "sp": "Holmes", "src": "audio/c3_4_08_01.mp3"}, {"t": "He often went down into the cellar.", "sp": "Holmes", "src": "audio/c3_4_08_02.mp3"}, {"t": "I thought he was digging a tunnel.", "sp": "Holmes", "src": "audio/c3_4_08_03.mp3"}, {"t": "I hit the pavement to see where the tunnel went.", "sp": "Holmes", "src": "audio/c3_4_08_04.mp3"}, {"t": "It was not in front.", "sp": "Holmes", "src": "audio/c3_4_08_05.mp3"}, {"t": "His knees were worn and dirty from digging.", "sp": "Holmes", "src": "audio/c3_4_08_06.mp3"}, {"t": "And behind the shop was the bank.", "sp": "Holmes", "src": "audio/c3_4_08_07.mp3"}, {"t": "When they closed the League, the tunnel was finished.", "sp": "Holmes", "src": "audio/c3_4_08_08.mp3"}, {"t": "Saturday gave them two days to escape.\"", "sp": "Holmes", "src": "audio/c3_4_08_09.mp3"}]}], "check": {"q": "홈즈가 2장에서 가게 앞 길바닥을 두드린 까닭은 뭐였나요?", "a": "땅굴이 가게 앞쪽으로 나 있는지 알아보려고요. 앞쪽은 아니었고, 가게 뒤에는 은행이 있었어요."}, "imgs": [{"at": 0, "src": "img/d5_b.jpg"}, {"at": 2, "src": "img/d5_c.jpg"}]}], "solve": {"after": 3, "intro": ["여기서 잠깐 멈춰요. 단서 수첩을 펼쳐서 1장부터 모은 단서를 다시 읽어 보세요. 그리고 홈즈보다 먼저 답을 골라 봐요. 고른 답은 저장해 두었다가, 이 장을 끝까지 읽은 뒤에 맞춰 봐요."], "qs": [{"q": "범인은 누구일까요? (Who is the criminal?)", "opts": ["① 윌슨 씨 (Mr. Wilson)", "② 은행에서 온 메리웨더 씨 (Mr. Merryweather)", "③ 윌슨 씨 가게의 조수 스폴딩 (Spaulding, the assistant)", "④ 경찰 존스 씨 (Mr. Jones)"]}, {"q": "범인은 무엇을 하려는 걸까요? (What is the plan?)", "opts": ["① 윌슨 씨 가게 지하실에서 은행 금고까지 땅굴을 파서, 금화를 훔치려고", "② 윌슨 씨가 사무실에 간 사이, 윌슨 씨 가게에 있는 물건을 몰래 훔치려고", "③ 밤에 은행 정문 자물쇠를 열고 몰래 들어가서, 금화를 훔치려고", "④ 빨간 머리 연맹에 모인 돈을 챙겨서, 멀리 달아나려고"]}]}, "solve_answers": [{"answer": "③", "label": "조수 스폴딩", "why": "땅굴에서 올라온 사람은 \"A young man with a boyish face\"였고, 홈즈는 그를 \"John Clay\"라고 불러요. 2장에서 윌슨 씨는 스폴딩이 서른은 넘었는데 얼굴에 수염이 없다고 했어요. 홈즈의 설명에서도 지하실에 자주 내려가던 조수가 땅굴을 파고 있었다고 해요. 그러니 존스가 얼굴을 몰랐던 존 클레이는 월급을 반만 받던 그 조수라고 볼 수 있어요. 원작에서도 홈즈가 조수를 알아보니 런던에서 손꼽히는 대담한 범죄자였다고 말해요. 빨간 머리 남자도 한패예요. 그 사람이 누구인지는 홈즈도 딱 잘라 말하지 않아요."}, {"answer": "①", "label": "지하실에서 은행까지 땅굴을 파서 금화를 훔치려고", "why": "홈즈는 지하실에 자주 내려가던 조수가 땅굴을 파고 있었다고 설명해요(\"I thought he was digging a tunnel.\"). 가게 뒤에는 은행이 있었고(\"And behind the shop was the bank.\"), 그 은행 지하 금고에 프랑스 금화가 3만 개 있었어요. 빨간 머리 연맹은 윌슨 씨를 날마다 가게 밖으로 내보내려고 꾸민 속임수였어요(\"The League was a trick to get Mr. Wilson out of his shop.\")."}], "clues": [{"ko": "존스가 쫓는 존 클레이는 젊고 아주 영리한 도둑이에요. 그런데 존스는 아직 그 얼굴을 본 적이 없어요.", "en": "John Clay is young and very clever. Jones has never seen his face."}, {"ko": "은행 지하 금고에 프랑스 금화가 3만 개 있어요.", "en": "There are thirty thousand French gold coins in the bank's cellar."}, {"ko": "금고 바닥을 지팡이로 치자 속이 빈 소리가 났어요. 홈즈는 무릎을 꿇고 돌 틈을 살펴봤어요.", "en": "The floor sounds hollow. Holmes looked at the cracks between the stones."}], "clue_intro": "오늘 읽은 내용에서 이 세 가지를 수첩에 적어 두세요. 「직접 풀어 보기」에서 쓸 거예요.", "quiz": [{"q": "What is in the cellar of the bank?", "ko": "은행 지하 금고에는 무엇이 있나요?", "opts": ["① old books", "② red wigs", "③ French gold coins", "④ newspapers"], "answer": "③", "why": "메리웨더 씨가 \"Our French gold is here,\"라고 속삭이고 \"We have thirty thousand gold coins.\"라고 말해요."}, {"q": "Why were the assistant's knees worn and dirty?", "ko": "조수의 바지 무릎은 왜 닳고 더러웠나요?", "opts": ["① He played football.", "② He cleaned the floor of the shop.", "③ He fell down the steps.", "④ He was digging a tunnel."], "answer": "④", "why": "홈즈가 \"I thought he was digging a tunnel.\"이라고 하고, 바로 \"His knees were worn and dirty from digging.\"이라고 설명해요. 2장에서 홈즈가 조수의 얼굴이 아니라 무릎을 본 까닭이 여기서 풀려요."}, {"q": "Why did the robbers come on Saturday night?", "ko": "범인들은 왜 토요일 밤에 왔을까요?", "opts": ["① It gave them two days to escape.", "② The bank was open on Sunday.", "③ Mr. Wilson was at the concert.", "④ Jones was at home."], "answer": "①", "why": "홈즈가 \"Saturday gave them two days to escape.\"라고 말해요. 토요일 밤에 훔치면 들키기 전까지 이틀 동안 멀리 달아날 수 있다는 뜻이에요."}, {"q": "\"Dear me! It sounds hollow!\" What does hollow mean here?", "ko": "여기서 hollow는 무슨 뜻일까요?", "opts": ["① very loud", "② empty inside", "③ very old", "④ full of water"], "answer": "②", "why": "바닥 밑에 땅굴이 뚫려 있어서, 돌바닥을 치자 속이 빈 소리가 났어요. 홈즈가 곧바로 조용히 하라고 하고(Please be quiet!) 돌 틈을 살핀 것도 그래서예요."}], "record": [{"t": "Now we must be silent and wait.", "src": "audio/c3_r0.mp3", "sp": "Holmes"}, {"t": "Jump, Archie, jump!", "src": "audio/c3_r1.mp3", "sp": "Clay"}, {"t": "It's no use, John Clay.", "src": "audio/c3_r2.mp3", "sp": "Holmes"}], "think": "", "reflect": null, "cert": null, "end": null, "words_read": 399}, "4": {"n": 4, "label": "4장", "title_en": "A Hat and a Goose", "title_ko": "모자 하나, 거위 한 마리", "new_text": false, "source": "원작: 아서 코난 도일, 「푸른 석류석(The Adventure of the Blue Carbuncle)」, 『셜록 홈즈의 모험』(Project Gutenberg #1661, 5858~6081행). 초6 눈높이(CEFR A2~B1 초반)로 쉽게 고쳐 쓴 글이에요.", "recap_title": "새 사건 소개", "recap": ["빨간 머리 연맹 사건은 끝났어요. 이번에는 크리스마스가 막 지난 런던이에요. 홈즈의 방 의자에 낡은 모자 하나가 걸려 있어요. 범죄도 없고 주인도 모르는 이 모자에서 홈즈는 무엇을 알아낼까요?"], "cards": [{"en": "Sherlock Holmes", "ko": "셜록 홈즈", "new": false, "line": "런던 베이커 가 221B에 사는 탐정이에요. 빨간 머리 연맹 사건에서 은행을 털려던 존 클레이를 붙잡았어요.", "img": "img/p_holmes.jpg"}, {"en": "Watson", "ko": "왓슨", "new": false, "line": "의사이고 홈즈의 친구예요. 이 이야기를 들려주는 '나(I)'예요. 크리스마스 인사를 하러 홈즈를 찾아왔어요.", "img": "img/p_watson.jpg"}, {"en": "Peterson", "ko": "피터슨", "new": true, "line": "제복을 입고 심부름이나 문지기 일을 하는 사람이에요(commissionaire). 홈즈와 왓슨이 잘 아는 사이예요. 크리스마스 새벽에 낡은 모자와 거위 한 마리를 주웠어요.", "img": "img/p_peterson.svg"}, {"en": "Henry Baker", "ko": "헨리 베이커", "new": true, "line": "거위 다리에 묶인 쪽지에 이름이 적힌 사람이에요. 모자 안에도 H. B.라는 글자가 있어요. 어디 사는 누구인지는 아직 몰라요.", "img": "img/p_henrybaker.svg"}], "words": [{"w": "goose", "ko": "거위", "ex": "A tall man was carrying a white goose.", "why": "이번 사건은 이 거위 한 마리에서 시작돼요.", "src": "audio/w_goose.mp3", "exsrc": "audio/c4_v0.mp3"}, {"w": "owner", "ko": "주인", "ex": "Its owner is unknown.", "why": "모자와 거위의 주인을 찾는 게 오늘의 문제예요.", "src": "audio/w_owner.mp3", "exsrc": "audio/c4_v1.mp3"}, {"w": "uniform", "ko": "제복", "ex": "But the man saw Peterson's uniform, dropped the goose and ran away.", "why": "모자 주인이 왜 달아났는지 알려 주는 말이에요.", "src": "audio/w_uniform.mp3", "exsrc": "audio/c4_v2.mp3"}, {"w": "lens", "ko": "돋보기", "ex": "A lens lay on the chair.", "why": "홈즈가 모자를 살펴볼 때 쓰는 도구예요.", "src": "audio/w_lens.mp3", "exsrc": "audio/c4_v3.mp3"}, {"w": "stain", "ko": "얼룩", "ex": "Some stains on it were covered with ink.", "why": "얼룩을 잉크로 가린 것도 하나의 단서예요.", "src": "audio/w_stain.mp3", "exsrc": "audio/c4_v4.mp3"}, {"w": "expensive", "ko": "비싼", "ex": "This hat was very expensive three years ago.", "why": "주인이 예전에는 돈이 있었다는 걸 보여 줘요.", "src": "audio/w_expensive.mp3", "exsrc": "audio/c4_v5.mp3"}, {"w": "candle", "ko": "양초", "ex": "He often walks upstairs at night with a candle.", "why": "촛농 자국에서 홈즈가 알아낸 사실이에요.", "src": "audio/w_candle.mp3", "exsrc": "audio/c4_v6.mp3"}], "scenes": [{"no": 1, "title": "크리스마스 새벽의 싸움", "paras": [{"kind": "p", "units": [{"t": "Two days after Christmas, I visited Holmes.", "sp": "Watson", "src": "audio/c4_1_00_00.mp3"}, {"t": "On a chair next to him hung an old, cracked hat.", "sp": "Watson", "src": "audio/c4_1_00_01.mp3"}, {"t": "A lens lay on the chair.", "sp": "Watson", "src": "audio/c4_1_00_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"Is it a crime?\"", "sp": "Watson", "src": "audio/c4_1_01_00.mp3"}, {"t": "I asked.", "sp": "Watson", "src": "audio/c4_1_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"No, no.", "sp": "Holmes", "src": "audio/c4_1_02_00.mp3"}, {"t": "No crime,\"", "sp": "Holmes", "src": "audio/c4_1_02_01.mp3"}, {"t": "said Holmes, laughing.", "sp": "Watson", "src": "audio/c4_1_02_02.mp3"}, {"t": "\"You know Peterson, the commissionaire?", "sp": "Holmes", "src": "audio/c4_1_02_03.mp3"}, {"t": "He found this hat.", "sp": "Holmes", "src": "audio/c4_1_02_04.mp3"}, {"t": "Its owner is unknown.", "sp": "Holmes", "src": "audio/c4_1_02_05.mp3"}]}, {"kind": "p", "units": [{"t": "\"At four o'clock on Christmas morning, Peterson was walking home.", "sp": "Holmes", "src": "audio/c4_1_03_00.mp3"}, {"t": "A tall man was carrying a white goose.", "sp": "Holmes", "src": "audio/c4_1_03_01.mp3"}, {"t": "He got into a fight with some rough men.", "sp": "Holmes", "src": "audio/c4_1_03_02.mp3"}, {"t": "One of them knocked off his hat.", "sp": "Holmes", "src": "audio/c4_1_03_03.mp3"}, {"t": "The man raised his stick and broke a shop window by mistake.", "sp": "Holmes", "src": "audio/c4_1_03_04.mp3"}, {"t": "Peterson ran to help him.", "sp": "Holmes", "src": "audio/c4_1_03_05.mp3"}, {"t": "But the man saw Peterson's uniform, dropped the goose and ran away.", "sp": "Holmes", "src": "audio/c4_1_03_06.mp3"}, {"t": "So Peterson had a hat and a goose.\"", "sp": "Holmes", "src": "audio/c4_1_03_07.mp3"}]}], "check": {"q": "피터슨은 어떻게 모자와 거위를 갖게 됐나요?", "a": "크리스마스 새벽에 싸움이 났는데, 모자 주인이 실수로 가게 유리창을 깼어요. 피터슨이 도우러 달려가자 그 사람은 제복을 보고 거위를 떨어뜨린 채 달아났어요. 그래서 모자와 거위가 피터슨에게 남았어요."}, "imgs": [{"at": 0, "src": "img/c4_a.svg"}, {"at": 3, "src": "img/c4_b.svg"}]}, {"no": 2, "title": "주인은 누구일까?", "paras": [{"kind": "p", "units": [{"t": "\"Did Peterson give them back to the owner?\"", "sp": "Watson", "src": "audio/c4_2_00_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"That is the problem.", "sp": "Holmes", "src": "audio/c4_2_01_00.mp3"}, {"t": "A card on the goose's leg said,", "sp": "Holmes", "src": "audio/c4_2_01_01.mp3"}, {"t": "'For Mrs. Henry Baker.'", "sp": "Holmes", "src": "audio/c4_2_01_02.mp3"}, {"t": "And the letters H. B. are inside the hat.", "sp": "Holmes", "src": "audio/c4_2_01_03.mp3"}, {"t": "But there are hundreds of Henry Bakers in London.\"", "sp": "Holmes", "src": "audio/c4_2_01_04.mp3"}]}, {"kind": "p", "units": [{"t": "\"So what did Peterson do?\"", "sp": "Watson", "src": "audio/c4_2_02_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"He brought the hat and the goose to me.", "sp": "Holmes", "src": "audio/c4_2_03_00.mp3"}, {"t": "The goose had to be eaten soon, so Peterson took it home.", "sp": "Holmes", "src": "audio/c4_2_03_01.mp3"}, {"t": "I still have the hat.\"", "sp": "Holmes", "src": "audio/c4_2_03_02.mp3"}]}], "check": {"q": "왜 주인에게 바로 돌려주지 못했나요?", "a": "거위 쪽지에 \"헨리 베이커 부인께\"라고 적혀 있고 모자에 H. B.라는 글자도 있지만, 런던에는 헨리 베이커가 수백 명이나 있어서 누구인지 알 수 없었어요."}, "imgs": []}, {"no": 3, "title": "아무것도 안 보여", "paras": [{"kind": "p", "units": [{"t": "\"But what can you learn from an old hat?\"", "sp": "Watson", "src": "audio/c4_3_00_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"Here is my lens.", "sp": "Holmes", "src": "audio/c4_3_01_00.mp3"}, {"t": "Look at it yourself.\"", "sp": "Holmes", "src": "audio/c4_3_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "I looked at it.", "sp": "Watson", "src": "audio/c4_3_02_00.mp3"}, {"t": "It was an old black hat.", "sp": "Watson", "src": "audio/c4_3_02_01.mp3"}, {"t": "There was a little loop for a string, but the string was gone.", "sp": "Watson", "src": "audio/c4_3_02_02.mp3"}, {"t": "Some stains on it were covered with ink.", "sp": "Watson", "src": "audio/c4_3_02_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"I can see nothing,\"", "sp": "Watson", "src": "audio/c4_3_03_00.mp3"}, {"t": "I said.", "sp": "Watson", "src": "audio/c4_3_03_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"On the contrary, Watson, you can see everything.", "sp": "Holmes", "src": "audio/c4_3_04_00.mp3"}, {"t": "But you do not think about what you see.\"", "sp": "Holmes", "src": "audio/c4_3_04_01.mp3"}]}], "check": {"q": "홈즈는 왓슨이 무엇을 못 한다고 했나요?", "a": "왓슨도 모든 것을 다 봤어요. 다만 본 것을 가지고 생각하지 않는다고 했어요."}, "imgs": []}, {"no": 4, "title": "모자가 들려주는 이야기", "paras": [{"kind": "p", "units": [{"t": "Holmes put the hat on his head.", "sp": "Watson", "src": "audio/c4_4_00_00.mp3"}, {"t": "It came right down over his nose!", "sp": "Watson", "src": "audio/c4_4_00_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"A man with such a big head must have something in it,\"", "sp": "Holmes", "src": "audio/c4_4_01_00.mp3"}, {"t": "he said.", "sp": "Watson", "src": "audio/c4_4_01_01.mp3"}, {"t": "\"This hat was very expensive three years ago.", "sp": "Holmes", "src": "audio/c4_4_01_02.mp3"}, {"t": "He has not bought a new hat since then.", "sp": "Holmes", "src": "audio/c4_4_01_03.mp3"}, {"t": "So he had money before, but he is poor now.", "sp": "Holmes", "src": "audio/c4_4_01_04.mp3"}]}, {"kind": "p", "units": [{"t": "\"He put a loop on his hat, so he was careful once.", "sp": "Holmes", "src": "audio/c4_4_02_00.mp3"}, {"t": "But now the string is broken, and he has not fixed it.", "sp": "Holmes", "src": "audio/c4_4_02_01.mp3"}, {"t": "Still, he covered the stains with ink.", "sp": "Holmes", "src": "audio/c4_4_02_02.mp3"}, {"t": "He still cares how he looks.", "sp": "Holmes", "src": "audio/c4_4_02_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"And look at these drops of candle wax.", "sp": "Holmes", "src": "audio/c4_4_03_00.mp3"}, {"t": "There are five.", "sp": "Holmes", "src": "audio/c4_4_03_01.mp3"}, {"t": "He often walks upstairs at night with a candle.", "sp": "Holmes", "src": "audio/c4_4_03_02.mp3"}, {"t": "So he probably has no gas lamps at home.\"", "sp": "Holmes", "src": "audio/c4_4_03_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"Very clever,\"", "sp": "Watson", "src": "audio/c4_4_04_00.mp3"}, {"t": "I said.", "sp": "Watson", "src": "audio/c4_4_04_01.mp3"}, {"t": "\"But no crime has happened.", "sp": "Watson", "src": "audio/c4_4_04_02.mp3"}, {"t": "Only a goose is lost.\"", "sp": "Watson", "src": "audio/c4_4_04_03.mp3"}]}], "check": {"q": "홈즈는 촛농 자국을 보고 무엇을 알아냈나요?", "a": "촛농이 다섯 군데나 묻어 있으니, 그 사람은 밤마다 촛불을 들고 계단을 올라가요. 그러니 집에 가스등이 없다고 봤어요."}, "imgs": [{"at": 0, "src": "img/c4_c.svg"}]}], "solve": null, "solve_answers": [], "clues": [{"ko": "거위 다리의 쪽지에 \"헨리 베이커 부인께\"라고 적혀 있고, 모자 안에는 H. B.라는 글자가 있어요.", "en": "A card on the goose's leg said, \"For Mrs. Henry Baker.\" The letters H. B. are inside the hat."}, {"ko": "모자 주인은 싸움 중에 유리창을 깨고, 제복 입은 피터슨을 보자 거위를 두고 달아났어요.", "en": "The owner broke a window, saw Peterson's uniform and ran away without the goose."}, {"ko": "홈즈가 모자로 알아낸 것: 머리가 크고, 예전에는 돈이 있었지만 지금은 가난하고, 집에 가스등이 없어 촛불을 써요.", "en": "The owner has a big head. He had money before, but he is poor now. He uses candles at home."}], "clue_intro": "오늘 읽은 내용에서 이 세 가지를 수첩에 적어 두세요.", "quiz": [{"q": "When did Peterson find the hat and the goose?", "ko": "피터슨은 모자와 거위를 언제 주웠나요?", "opts": ["① two days after Christmas", "② on Christmas night", "③ at four o'clock on Christmas morning", "④ this morning"], "answer": "③", "why": "홈즈가 \"At four o'clock on Christmas morning, Peterson was walking home.\"이라고 말해요. ①은 왓슨이 홈즈를 찾아간 날이에요."}, {"q": "Why did the man drop the goose and run away?", "ko": "모자 주인은 왜 거위를 떨어뜨리고 달아났나요?", "opts": ["① He saw Peterson's uniform.", "② The goose was too heavy.", "③ He wanted to catch the rough men.", "④ He was late for dinner."], "answer": "①", "why": "\"But the man saw Peterson's uniform, dropped the goose and ran away.\"라고 나와요. 바로 앞에서 실수로 가게 유리창을 깼으니, 제복 입은 사람을 보고 겁이 났을 거예요."}, {"q": "Why does Holmes think the owner is poor now?", "ko": "홈즈는 왜 모자 주인이 지금은 가난하다고 생각했나요?", "opts": ["① The hat is too big for him.", "② There are drops of candle wax on the hat.", "③ The letters H. B. are inside the hat.", "④ The hat was expensive three years ago, and he has not bought a new one."], "answer": "④", "why": "\"This hat was very expensive three years ago. He has not bought a new hat since then. So he had money before, but he is poor now.\" ② 촛농은 집에 가스등이 없다는 단서예요."}, {"q": "\"Some stains on it were covered with ink.\" What is a stain?", "ko": "여기서 stain은 무엇일까요?", "opts": ["① a dirty mark", "② a small hole", "③ a letter", "④ a piece of string"], "answer": "①", "why": "모자에 묻은 지저분한 자국을 잉크로 칠해 가렸다는 말이에요. 홈즈는 이걸 보고 \"He still cares how he looks.\"라고 해요. ④ 끈(string)은 따로 나와요(the string was gone)."}], "record": [{"t": "No, no. No crime.", "src": "audio/c4_r0.mp3", "sp": "Holmes"}, {"t": "I can see nothing.", "src": "audio/c4_r1.mp3", "sp": "Watson"}, {"t": "On the contrary, Watson, you can see everything.", "src": "audio/c4_r2.mp3", "sp": "Holmes"}], "think": "", "reflect": null, "cert": null, "end": null, "words_read": 399}, "5": {"n": 5, "label": "5장", "title_en": "The Stone in the Goose", "title_ko": "거위 속의 보석", "new_text": false, "source": "원작: 아서 코난 도일, 「푸른 석류석(The Adventure of the Blue Carbuncle)」, 『셜록 홈즈의 모험』(Project Gutenberg #1661, 6083~6327행). 초6 눈높이(CEFR A2~B1 초반)로 쉽게 고쳐 쓴 글이에요.", "recap_title": "지난 이야기", "recap": ["크리스마스 새벽, 피터슨은 싸움 끝에 달아난 남자가 떨어뜨린 낡은 모자와 거위를 주웠어요. 거위 다리에는 \"헨리 베이커 부인께\"라는 쪽지가 있었어요. 홈즈는 모자만 보고 주인이 머리가 크고, 예전보다 가난해졌고, 집에서 촛불을 쓴다는 걸 알아냈어요. 거위는 피터슨이 집에 가져갔어요."], "cards": [{"en": "Sherlock Holmes", "ko": "셜록 홈즈", "new": false, "line": "런던 베이커 가 221B에 사는 탐정이에요. 낡은 모자 하나로 주인이 어떤 사람인지 알아맞혔어요.", "img": "img/p_holmes.jpg"}, {"en": "Watson", "ko": "왓슨", "new": false, "line": "의사이고 홈즈의 친구예요. 이 이야기를 들려주는 '나(I)'예요.", "img": "img/p_watson.jpg"}, {"en": "Peterson", "ko": "피터슨", "new": false, "line": "제복을 입고 심부름이나 문지기 일을 하는 사람이에요. 크리스마스 새벽에 모자와 거위를 주웠고, 거위는 집에 가져갔어요.", "img": "img/p_peterson.svg"}, {"en": "Henry Baker", "ko": "헨리 베이커", "new": false, "line": "모자와 거위의 주인으로 보이는 사람이에요. 오늘 홈즈의 신문 광고를 보고 찾아와요.", "img": "img/p_henrybaker.svg"}, {"en": "John Horner", "ko": "존 호너", "new": true, "line": "배관공이에요. 호텔에서 보석을 훔쳤다는 의심을 받고 잡혀갔어요. 자기는 죄가 없다고 해요.", "img": "img/p_horner.svg"}, {"en": "James Ryder", "ko": "제임스 라이더", "new": true, "line": "코스모폴리탄 호텔 직원이에요. 신문 기사에 따르면 호너를 백작부인 방에 데려갔고, 보석 상자가 빈 걸 보고 사람들을 불렀어요.", "img": "img/p_ryder.svg"}], "words": [{"w": "stone", "ko": "돌, 보석", "ex": "In his hand was a bright blue stone.", "why": "거위 속에서 나온 파란 보석이에요. 이제 사건이 진짜 사건이 돼요.", "src": "audio/w_stone.mp3", "exsrc": "audio/c5_v0.mp3"}, {"w": "reward", "ko": "보상금", "ex": "There is a reward of a thousand pounds for it.", "why": "보석을 찾아 주면 받는 돈이에요. 그만큼 귀한 보석이에요.", "src": "audio/w_reward.mp3", "exsrc": "audio/c5_v1.mp3"}, {"w": "steal", "ko": "훔치다 (stolen 도둑맞은)", "ex": "It was stolen at the Hotel Cosmopolitan.", "why": "보석이 원래 있던 곳과 사라진 때를 알려 줘요.", "src": "audio/w_steal.mp3", "exsrc": "audio/c5_v2.mp3"}, {"w": "plumber", "ko": "배관공", "ex": "John Horner, a plumber, was arrested.", "why": "범인으로 의심받아 잡혀간 사람의 직업이에요.", "src": "audio/w_plumber.mp3", "exsrc": "audio/c5_v3.mp3"}, {"w": "arrest", "ko": "체포하다 (arrested 체포된)", "ex": "Horner was arrested that evening, but the stone was not found.", "why": "호너가 잡혀갔지만 보석은 나오지 않았어요. 이상한 점이에요.", "src": "audio/w_arrest.mp3", "exsrc": "audio/c5_v4.mp3"}, {"w": "innocent", "ko": "죄가 없는", "ex": "Horner said that he was innocent.", "why": "호너는 자기가 훔치지 않았다고 해요. 정말일까요?", "src": "audio/w_innocent.mp3", "exsrc": "audio/c5_v5.mp3"}, {"w": "insides", "ko": "(몸) 속, 내장", "ex": "We still have the feathers and the insides of your own bird.", "why": "보석이 들어 있던 곳이에요. 헨리 베이커가 이걸 원하지 않은 게 단서예요.", "src": "audio/w_insides.mp3", "exsrc": "audio/c5_v6.mp3"}], "scenes": [{"no": 1, "title": "거위 속에서 나온 것", "paras": [{"kind": "p", "units": [{"t": "Then the door flew open.", "sp": "Watson", "src": "audio/c5_1_00_00.mp3"}, {"t": "Peterson rushed in.", "sp": "Watson", "src": "audio/c5_1_00_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"The goose, Mr. Holmes!", "sp": "Peterson", "src": "audio/c5_1_01_00.mp3"}, {"t": "The goose!\"", "sp": "Peterson", "src": "audio/c5_1_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"What?", "sp": "Holmes", "src": "audio/c5_1_02_00.mp3"}, {"t": "Has it come back to life and flown away?\"", "sp": "Holmes", "src": "audio/c5_1_02_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Look!", "sp": "Peterson", "src": "audio/c5_1_03_00.mp3"}, {"t": "See what my wife found inside it!\"", "sp": "Peterson", "src": "audio/c5_1_03_01.mp3"}]}, {"kind": "p", "units": [{"t": "In his hand was a bright blue stone.", "sp": "Watson", "src": "audio/c5_1_04_00.mp3"}, {"t": "It was smaller than a bean, but it shone brightly.", "sp": "Watson", "src": "audio/c5_1_04_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"It's the Countess of Morcar's blue carbuncle!\"", "sp": "Watson", "src": "audio/c5_1_05_00.mp3"}, {"t": "I cried.", "sp": "Watson", "src": "audio/c5_1_05_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Yes,\"", "sp": "Holmes", "src": "audio/c5_1_06_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c5_1_06_01.mp3"}, {"t": "\"There is a reward of a thousand pounds for it.\"", "sp": "Holmes", "src": "audio/c5_1_06_02.mp3"}]}], "check": {"q": "피터슨의 아내는 거위 속에서 무엇을 찾았나요?", "a": "콩보다 작은 파란 보석이에요. 모카 백작부인이 잃어버린 '푸른 석류석'이고, 찾아 주면 1,000파운드를 준대요."}, "imgs": [{"at": 0, "src": "img/c5_a.svg"}]}, {"no": 2, "title": "신문 기사", "paras": [{"kind": "p", "units": [{"t": "\"It was stolen at the Hotel Cosmopolitan,\"", "sp": "Watson", "src": "audio/c5_2_00_00.mp3"}, {"t": "I said.", "sp": "Watson", "src": "audio/c5_2_00_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Yes, five days ago,\"", "sp": "Holmes", "src": "audio/c5_2_01_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c5_2_01_01.mp3"}, {"t": "He read from a newspaper.", "sp": "Watson", "src": "audio/c5_2_01_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"John Horner, a plumber, was arrested.", "sp": "Holmes", "src": "audio/c5_2_02_00.mp3"}, {"t": "James Ryder, a hotel worker, took Horner up to the Countess's room.", "sp": "Holmes", "src": "audio/c5_2_02_01.mp3"}, {"t": "Horner had to fix the fireplace.", "sp": "Holmes", "src": "audio/c5_2_02_02.mp3"}, {"t": "Then Ryder was called away.", "sp": "Holmes", "src": "audio/c5_2_02_03.mp3"}, {"t": "When he came back, Horner was gone, and the jewel box was empty.", "sp": "Holmes", "src": "audio/c5_2_02_04.mp3"}, {"t": "Ryder shouted for help.", "sp": "Holmes", "src": "audio/c5_2_02_05.mp3"}, {"t": "Horner was arrested that evening, but the stone was not found.", "sp": "Holmes", "src": "audio/c5_2_02_06.mp3"}, {"t": "Horner said that he was innocent.\"", "sp": "Holmes", "src": "audio/c5_2_02_07.mp3"}]}, {"kind": "p", "units": [{"t": "\"How did the stone get from a jewel box into a goose?\"", "sp": "Holmes", "src": "audio/c5_2_03_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c5_2_03_01.mp3"}, {"t": "\"First, we must find Henry Baker.\"", "sp": "Holmes", "src": "audio/c5_2_03_02.mp3"}]}], "check": {"q": "신문 기사에 따르면 보석 상자가 빈 걸 보고 사람들을 부른 사람은 누구인가요?", "a": "호텔 직원 제임스 라이더예요. 라이더가 배관공 호너를 백작부인 방에 데려갔다가 잠깐 자리를 비웠고, 돌아와 보니 보석 상자가 비어 있어서 사람들을 불렀대요."}, "imgs": []}, {"no": 3, "title": "신문 광고", "paras": [{"kind": "p", "units": [{"t": "Holmes wrote an advertisement for the evening newspapers.", "sp": "Watson", "src": "audio/c5_3_00_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"Found at the corner of Goodge Street, a goose and a black felt hat.", "sp": "Holmes", "src": "audio/c5_3_01_00.mp3"}, {"t": "Mr. Henry Baker can have the same at 6:30 this evening at 221B, Baker Street.\"", "sp": "Holmes", "src": "audio/c5_3_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Peterson, take this to the newspapers.", "sp": "Holmes", "src": "audio/c5_3_02_00.mp3"}, {"t": "And buy a goose on your way back.\"", "sp": "Holmes", "src": "audio/c5_3_02_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Is Horner innocent?\"", "sp": "Watson", "src": "audio/c5_3_03_00.mp3"}, {"t": "I asked.", "sp": "Watson", "src": "audio/c5_3_03_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"I cannot tell.", "sp": "Holmes", "src": "audio/c5_3_04_00.mp3"}, {"t": "But I think Henry Baker knows nothing.", "sp": "Holmes", "src": "audio/c5_3_04_01.mp3"}, {"t": "I will find out with a simple test.\"", "sp": "Holmes", "src": "audio/c5_3_04_02.mp3"}]}], "check": {"q": "홈즈는 왜 피터슨에게 거위를 사 오라고 했을까요?", "a": "헨리 베이커의 거위는 피터슨이 집에 가져가 먹기로 했으니까요. 광고를 보고 찾아올 헨리 베이커에게 대신 줄 거위가 필요해요."}, "imgs": [{"at": 0, "src": "img/c5_b.svg"}]}, {"no": 4, "title": "헨리 베이커가 찾아오다", "paras": [{"kind": "p", "units": [{"t": "A little after half past six, Henry Baker came.", "sp": "Watson", "src": "audio/c5_4_00_00.mp3"}, {"t": "He was a large man with a big head and a grey-brown beard.", "sp": "Watson", "src": "audio/c5_4_00_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Why didn't you put an advertisement in the newspaper?\"", "sp": "Holmes", "src": "audio/c5_4_01_00.mp3"}, {"t": "asked Holmes.", "sp": "Watson", "src": "audio/c5_4_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"I don't have much money these days,\"", "sp": "HenryBaker", "src": "audio/c5_4_02_00.mp3"}, {"t": "he said.", "sp": "Watson", "src": "audio/c5_4_02_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"We had to eat your goose,\"", "sp": "Holmes", "src": "audio/c5_4_03_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c5_4_03_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Eat it!\"", "sp": "HenryBaker", "src": "audio/c5_4_04_00.mp3"}, {"t": "Mr. Baker almost jumped up from his chair.", "sp": "Watson", "src": "audio/c5_4_04_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"But here is another one.\"", "sp": "Holmes", "src": "audio/c5_4_05_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"Oh, certainly, certainly,\"", "sp": "HenryBaker", "src": "audio/c5_4_06_00.mp3"}, {"t": "said Mr. Baker.", "sp": "Watson", "src": "audio/c5_4_06_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"We still have the feathers and the insides of your own bird.", "sp": "Holmes", "src": "audio/c5_4_07_00.mp3"}, {"t": "Do you want them?\"", "sp": "Holmes", "src": "audio/c5_4_07_01.mp3"}]}, {"kind": "p", "units": [{"t": "He laughed.", "sp": "Watson", "src": "audio/c5_4_08_00.mp3"}, {"t": "\"No, sir.", "sp": "HenryBaker", "src": "audio/c5_4_08_01.mp3"}, {"t": "I will just take this nice new bird.\"", "sp": "HenryBaker", "src": "audio/c5_4_08_02.mp3"}]}, {"kind": "p", "units": [{"t": "Holmes looked at me.", "sp": "Watson", "src": "audio/c5_4_09_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"Where did you get your goose?\"", "sp": "Holmes", "src": "audio/c5_4_10_00.mp3"}, {"t": "asked Holmes.", "sp": "Watson", "src": "audio/c5_4_10_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"From the Alpha Inn.", "sp": "HenryBaker", "src": "audio/c5_4_11_00.mp3"}, {"t": "We had a goose club there.", "sp": "HenryBaker", "src": "audio/c5_4_11_01.mp3"}, {"t": "We paid a few pennies every week.", "sp": "HenryBaker", "src": "audio/c5_4_11_02.mp3"}, {"t": "We each got a goose at Christmas.\"", "sp": "HenryBaker", "src": "audio/c5_4_11_03.mp3"}]}, {"kind": "p", "units": [{"t": "When he left, Holmes said,", "sp": "Watson", "src": "audio/c5_4_12_00.mp3"}, {"t": "\"He knows nothing about the stone.", "sp": "Holmes", "src": "audio/c5_4_12_01.mp3"}, {"t": "Let's follow this clue.\"", "sp": "Holmes", "src": "audio/c5_4_12_02.mp3"}]}], "check": {"q": "홈즈는 어떻게 헨리 베이커가 보석을 모른다고 판단했나요?", "a": "원래 거위의 깃털과 속을 가져가겠냐고 물었더니, 헨리 베이커는 웃으면서 필요 없다고 했어요. 거위 속에 보석이 있는 걸 알았다면 그렇게 하지 않았겠지요. 이것이 홈즈의 '간단한 시험'이었어요."}, "imgs": [{"at": 0, "src": "img/c5_c.svg"}]}], "solve": null, "solve_answers": [], "clues": [{"ko": "보석은 호텔 백작부인의 방에서 없어졌어요. 배관공 호너가 잡혀갔지만, 보석은 나오지 않았어요.", "en": "The stone was stolen in a hotel room. Horner was arrested, but the stone was not found."}, {"ko": "신문 기사에 따르면 호텔 직원 라이더가 호너를 방에 데려갔어요. 돌아와서 보석 상자가 빈 걸 보고 사람들을 부른 것도 라이더예요.", "en": "Ryder took Horner up to the room. Ryder shouted for help."}, {"ko": "헨리 베이커는 원래 거위의 속에 관심이 없었어요. 그 거위는 알파 인의 거위 모임에서 받은 거예요.", "en": "Henry Baker did not want the insides of his goose. He got it from a goose club at the Alpha Inn."}], "clue_intro": "오늘 읽은 내용에서 이 세 가지를 수첩에 적어 두세요.", "quiz": [{"q": "What did Peterson's wife find inside the goose?", "ko": "피터슨의 아내는 거위 속에서 무엇을 찾았나요?", "opts": ["① a gold coin", "② a blue stone", "③ a small key", "④ a letter"], "answer": "②", "why": "\"In his hand was a bright blue stone. It was smaller than a bean, but it shone brightly.\"라고 나와요."}, {"q": "Who was arrested for stealing the stone?", "ko": "보석을 훔쳤다고 잡혀간 사람은 누구인가요?", "opts": ["① James Ryder, a hotel worker", "② Henry Baker", "③ Peterson", "④ John Horner, a plumber"], "answer": "④", "why": "신문 기사가 \"John Horner, a plumber, was arrested.\"로 시작해요. ① 라이더는 호너를 방에 데려가고 도움을 부른 사람이에요."}, {"q": "Why did Holmes think that Henry Baker knew nothing about the stone?", "ko": "홈즈는 왜 헨리 베이커가 보석을 모른다고 생각했나요?", "opts": ["① He did not want the insides of his own goose.", "② He did not have much money.", "③ He came at half past six.", "④ He had a big head."], "answer": "①", "why": "홈즈가 \"We still have the feathers and the insides of your own bird. Do you want them?\"이라고 묻자 헨리 베이커는 웃으며 \"No, sir.\"라고 해요. 거위 속에 보석이 있는 걸 알았다면 꼭 가져가려 했겠지요. ②, ③, ④도 본문에 나오는 사실이지만, 보석을 모른다는 근거는 아니에요."}, {"q": "\"Horner said that he was innocent.\" What does innocent mean here?", "ko": "여기서 innocent는 무슨 뜻일까요?", "opts": ["① He was very young.", "② He did nothing wrong.", "③ He was very rich.", "④ He was very angry."], "answer": "②", "why": "호너는 잡혀갔지만 보석은 나오지 않았고, 자기는 훔치지 않았다고 해요. 그래서 왓슨도 \"Is Horner innocent?\"라고 물어요."}], "record": [{"t": "The goose, Mr. Holmes! The goose!", "src": "audio/c5_r0.mp3", "sp": "Peterson"}, {"t": "Has it come back to life and flown away?", "src": "audio/c5_r1.mp3", "sp": "Holmes"}, {"t": "I will find out with a simple test.", "src": "audio/c5_r2.mp3", "sp": "Holmes"}], "think": "", "reflect": null, "cert": null, "end": null, "words_read": 400}, "6": {"n": 6, "label": "6장", "title_en": "Follow the Goose", "title_ko": "거위를 따라가라", "new_text": false, "source": "원작: 아서 코난 도일, 「푸른 석류석(The Adventure of the Blue Carbuncle)」, 『셜록 홈즈의 모험』(Project Gutenberg #1661, 6326~6778행). 초6 눈높이(CEFR A2~B1 초반)로 쉽게 고쳐 쓴 글이에요.", "recap_title": "지난 이야기", "recap": ["피터슨이 가져간 거위 속에서 파란 보석이 나왔어요. 호텔에서 도둑맞은 백작부인의 보석이에요. 배관공 호너가 잡혀갔지만 보석은 찾지 못했어요. 헨리 베이커는 보석을 전혀 모르는 사람이었고, 거위는 알파 인의 거위 모임에서 받았대요. 홈즈와 왓슨은 거위가 온 길을 거꾸로 따라가요."], "cards": [{"en": "Sherlock Holmes", "ko": "셜록 홈즈", "new": false, "line": "런던 베이커 가 221B에 사는 탐정이에요. 거위가 어디서 왔는지 거꾸로 따라가요.", "img": "img/p_holmes.jpg"}, {"en": "Watson", "ko": "왓슨", "new": false, "line": "의사이고 홈즈의 친구예요. 이 이야기를 들려주는 '나(I)'예요.", "img": "img/p_watson.jpg"}, {"en": "Breckinridge", "ko": "브레킨리지", "new": true, "line": "코벤트 가든 시장에서 거위를 파는 상인이에요. 알파 인에 거위를 팔았어요. 그 거위 이야기만 나오면 화를 내요.", "img": "img/p_breckinridge.svg"}, {"en": "Mrs. Oakshott", "ko": "오크쇼트 부인", "new": true, "line": "브릭스턴 로드에 사는 사람이에요. 브레킨리지의 장부에 이름이 있어요.", "img": "img/p_oakshott.svg"}, {"en": "James Ryder", "ko": "제임스 라이더", "new": false, "line": "코스모폴리탄 호텔 직원이에요. 신문 기사에 따르면 호너를 백작부인 방에 데려갔고, 보석 상자가 빈 걸 보고 사람들을 불렀어요.", "img": "img/p_ryder.svg"}, {"en": "John Horner", "ko": "존 호너", "new": false, "line": "보석을 훔쳤다는 의심을 받고 잡혀간 배관공이에요. 자기는 죄가 없다고 해요.", "img": "img/p_horner.svg"}], "words": [{"w": "salesman", "ko": "상인, 장사하는 사람", "ex": "I bought them from Breckinridge, a salesman at Covent Garden Market.", "why": "거위가 지나간 길의 한 사람이에요.", "src": "audio/w_salesman.mp3", "exsrc": "audio/c6_v0.mp3"}, {"w": "prison", "ko": "감옥", "ex": "If we fail, a man may go to prison for seven years.", "why": "홈즈가 서두르는 까닭이에요. 잘못하면 호너가 감옥에 갈 수 있어요.", "src": "audio/w_prison.mp3", "exsrc": "audio/c6_v1.mp3"}, {"w": "bet", "ko": "내기하다", "ex": "Will you bet on it?", "why": "홈즈가 브레킨리지의 입을 연 방법이에요.", "src": "audio/w_bet.mp3", "exsrc": "audio/c6_v2.mp3"}, {"w": "real", "ko": "진짜의", "ex": "No, no. The real name.", "why": "작은 남자가 가짜 이름을 댔다는 걸 홈즈가 알아챘어요.", "src": "audio/w_real.mp3", "exsrc": "audio/c6_v3.mp3"}, {"w": "tail", "ko": "꼬리", "ex": "It has a black bar across its tail.", "why": "보석을 삼킨 거위를 알아보는 표시예요.", "src": "audio/w_tail.mp3", "exsrc": "audio/c6_v4.mp3"}, {"w": "stall", "ko": "가게, 노점", "ex": "A little man with a face like a rat stood at the stall.", "why": "시장에서 거위를 파는 브레킨리지의 가게예요.", "src": "audio/w_stall.mp3", "exsrc": "audio/c6_v5.mp3"}, {"w": "forgiveness", "ko": "용서", "ex": "Besides, it is the season of forgiveness.", "why": "홈즈가 라이더를 보내 준 까닭 가운데 하나예요.", "src": "audio/w_forgiveness.mp3", "exsrc": "audio/c6_v6.mp3"}], "scenes": [{"no": 1, "title": "시장의 거위 장수", "paras": [{"kind": "p", "units": [{"t": "We walked to the Alpha Inn.", "sp": "Watson", "src": "audio/c6_1_00_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"Your geese are very good,\"", "sp": "Holmes", "src": "audio/c6_1_01_00.mp3"}, {"t": "Holmes said to the owner.", "sp": "Watson", "src": "audio/c6_1_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"They're not our geese.", "sp": "Innkeeper", "src": "audio/c6_1_02_00.mp3"}, {"t": "I bought them from Breckinridge, a salesman at Covent Garden Market.\"", "sp": "Innkeeper", "src": "audio/c6_1_02_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Remember, Watson,\"", "sp": "Holmes", "src": "audio/c6_1_03_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c6_1_03_01.mp3"}, {"t": "\"If we fail, a man may go to prison for seven years.\"", "sp": "Holmes", "src": "audio/c6_1_03_02.mp3"}]}, {"kind": "p", "units": [{"t": "Holmes asked Breckinridge,", "sp": "Watson", "src": "audio/c6_1_04_00.mp3"}, {"t": "\"Where did you get the Alpha's geese?\"", "sp": "Holmes", "src": "audio/c6_1_04_01.mp3"}]}, {"kind": "p", "units": [{"t": "The salesman got angry.", "sp": "Watson", "src": "audio/c6_1_05_00.mp3"}, {"t": "\"I won't tell you!", "sp": "Breckinridge", "src": "audio/c6_1_05_01.mp3"}, {"t": "Everyone keeps asking me about those geese!\"", "sp": "Breckinridge", "src": "audio/c6_1_05_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"I bet the goose I ate came from the country,\"", "sp": "Holmes", "src": "audio/c6_1_06_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c6_1_06_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"You're wrong.", "sp": "Breckinridge", "src": "audio/c6_1_07_00.mp3"}, {"t": "It came from the town!", "sp": "Breckinridge", "src": "audio/c6_1_07_01.mp3"}, {"t": "Will you bet on it?\"", "sp": "Breckinridge", "src": "audio/c6_1_07_02.mp3"}, {"t": "said the salesman.", "sp": "Watson", "src": "audio/c6_1_07_03.mp3"}]}, {"kind": "p", "units": [{"t": "A boy brought the books.", "sp": "Watson", "src": "audio/c6_1_08_00.mp3"}, {"t": "Holmes read,", "sp": "Watson", "src": "audio/c6_1_08_01.mp3"}, {"t": "\"Mrs. Oakshott, 117 Brixton Road.", "sp": "Holmes", "src": "audio/c6_1_08_02.mp3"}, {"t": "December 22nd.", "sp": "Holmes", "src": "audio/c6_1_08_03.mp3"}, {"t": "Twenty-four geese.", "sp": "Holmes", "src": "audio/c6_1_08_04.mp3"}, {"t": "Sold to the Alpha.\"", "sp": "Holmes", "src": "audio/c6_1_08_05.mp3"}]}, {"kind": "p", "units": [{"t": "Holmes paid a gold coin and walked away.", "sp": "Watson", "src": "audio/c6_1_09_00.mp3"}, {"t": "\"If you want facts from a man like that, make a bet with him.\"", "sp": "Holmes", "src": "audio/c6_1_09_01.mp3"}]}], "check": {"q": "홈즈는 어떻게 브레킨리지에게서 거위를 산 곳을 알아냈나요?", "a": "그냥 물어보니 화를 내며 말해 주지 않았어요. 그래서 홈즈는 일부러 거위가 시골에서 왔다고 내기를 걸었어요. 브레킨리지는 이기려고 장부를 가져오게 했고, 거기에 오크쇼트 부인의 이름이 있었어요. 홈즈는 내기에 져서 금화를 냈지만, 알고 싶던 걸 알아냈어요."}, "imgs": [{"at": 4, "src": "img/c6_a.svg"}]}, {"no": 2, "title": "쫓겨난 작은 남자", "paras": [{"kind": "p", "units": [{"t": "Suddenly, we heard shouting.", "sp": "Watson", "src": "audio/c6_2_00_00.mp3"}, {"t": "A little man with a face like a rat stood at the stall.", "sp": "Watson", "src": "audio/c6_2_00_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"I've had enough of you and your geese!\"", "sp": "Breckinridge", "src": "audio/c6_2_01_00.mp3"}, {"t": "shouted Breckinridge.", "sp": "Watson", "src": "audio/c6_2_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"One of them was mine,\"", "sp": "Ryder", "src": "audio/c6_2_02_00.mp3"}, {"t": "said the little man.", "sp": "Watson", "src": "audio/c6_2_02_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Then ask Mrs. Oakshott for it!\"", "sp": "Breckinridge", "src": "audio/c6_2_03_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"She told me to ask you!\"", "sp": "Ryder", "src": "audio/c6_2_04_00.mp3"}]}, {"kind": "p", "units": [{"t": "Breckinridge rushed at him, and the little man ran into the dark.", "sp": "Watson", "src": "audio/c6_2_05_00.mp3"}]}], "check": {"q": "작은 남자는 브레킨리지에게 무엇을 물어보고 있었나요?", "a": "거위예요. \"그중 한 마리는 내 것\"이라며 그 거위 일로 찾아왔어요. 오크쇼트 부인이 브레킨리지에게 물어보라고 했대요."}, "imgs": [{"at": 0, "src": "img/c6_b.svg"}]}, {"no": 3, "title": "진짜 이름", "paras": [{"kind": "p", "units": [{"t": "Holmes caught up with him.", "sp": "Watson", "src": "audio/c6_3_00_00.mp3"}, {"t": "\"I am Sherlock Holmes.", "sp": "Holmes", "src": "audio/c6_3_00_01.mp3"}, {"t": "You are looking for some geese.", "sp": "Holmes", "src": "audio/c6_3_00_02.mp3"}, {"t": "Who are you?\"", "sp": "Holmes", "src": "audio/c6_3_00_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"My name is John Robinson,\"", "sp": "Ryder", "src": "audio/c6_3_01_00.mp3"}, {"t": "the man said.", "sp": "Watson", "src": "audio/c6_3_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"No, no.", "sp": "Holmes", "src": "audio/c6_3_02_00.mp3"}, {"t": "The real name.\"", "sp": "Holmes", "src": "audio/c6_3_02_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"James Ryder.\"", "sp": "Ryder", "src": "audio/c6_3_03_00.mp3"}]}, {"kind": "p", "units": [{"t": "At Baker Street, Holmes said,", "sp": "Watson", "src": "audio/c6_3_04_00.mp3"}, {"t": "\"You want a white goose.", "sp": "Holmes", "src": "audio/c6_3_04_01.mp3"}, {"t": "It has a black bar across its tail.\"", "sp": "Holmes", "src": "audio/c6_3_04_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"Yes!", "sp": "Ryder", "src": "audio/c6_3_05_00.mp3"}, {"t": "Where did it go?\"", "sp": "Ryder", "src": "audio/c6_3_05_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"It came here.", "sp": "Holmes", "src": "audio/c6_3_06_00.mp3"}, {"t": "It laid an egg after it was dead.", "sp": "Holmes", "src": "audio/c6_3_06_01.mp3"}, {"t": "A bright blue egg.\"", "sp": "Holmes", "src": "audio/c6_3_06_02.mp3"}]}, {"kind": "p", "units": [{"t": "Ryder nearly fell down.", "sp": "Watson", "src": "audio/c6_3_07_00.mp3"}, {"t": "Holmes held up the blue stone.", "sp": "Watson", "src": "audio/c6_3_07_01.mp3"}]}], "check": {"q": "홈즈가 \"죽은 뒤에 알을 낳았다\"고 한 건 무슨 뜻일까요?", "a": "거위 속에서 나온 파란 보석을 농담처럼 '파란 알'이라고 부른 거예요. 라이더는 그 말을 듣고 쓰러질 뻔했고, 홈즈는 보석을 들어 보였어요."}, "imgs": [{"at": 6, "src": "img/c6_c.svg"}]}, {"no": 4, "title": "크리스마스의 용서", "paras": [{"kind": "p", "units": [{"t": "\"You stole the stone,\"", "sp": "Holmes", "src": "audio/c6_4_00_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c6_4_00_01.mp3"}, {"t": "\"You knew Horner had been in trouble before.", "sp": "Holmes", "src": "audio/c6_4_00_02.mp3"}, {"t": "So the police would blame him.\"", "sp": "Holmes", "src": "audio/c6_4_00_03.mp3"}, {"t": "Ryder did not say no.", "sp": "Watson", "src": "audio/c6_4_00_04.mp3"}, {"t": "He told us the rest.", "sp": "Watson", "src": "audio/c6_4_00_05.mp3"}]}, {"kind": "p", "units": [{"t": "He went to his sister's house.", "sp": "Watson", "src": "audio/c6_4_01_00.mp3"}, {"t": "She was Mrs. Oakshott.", "sp": "Watson", "src": "audio/c6_4_01_01.mp3"}, {"t": "She kept geese there.", "sp": "Watson", "src": "audio/c6_4_01_02.mp3"}, {"t": "He pushed the stone down a goose's throat.", "sp": "Watson", "src": "audio/c6_4_01_03.mp3"}, {"t": "But the goose got away.", "sp": "Watson", "src": "audio/c6_4_01_04.mp3"}, {"t": "There were two white geese with a black bar on the tail.", "sp": "Watson", "src": "audio/c6_4_01_05.mp3"}, {"t": "Ryder took the wrong one.", "sp": "Watson", "src": "audio/c6_4_01_06.mp3"}]}, {"kind": "p", "units": [{"t": "Holmes opened the door.", "sp": "Watson", "src": "audio/c6_4_02_00.mp3"}, {"t": "\"Get out!\"", "sp": "Holmes", "src": "audio/c6_4_02_01.mp3"}]}, {"kind": "p", "units": [{"t": "Ryder ran down the stairs.", "sp": "Watson", "src": "audio/c6_4_03_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"He won't speak against Horner.", "sp": "Holmes", "src": "audio/c6_4_04_00.mp3"}, {"t": "So the case against Horner will fall apart,\"", "sp": "Holmes", "src": "audio/c6_4_04_01.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c6_4_04_02.mp3"}, {"t": "\"And he is too frightened to do wrong again.", "sp": "Holmes", "src": "audio/c6_4_04_03.mp3"}, {"t": "Besides, it is the season of forgiveness.\"", "sp": "Holmes", "src": "audio/c6_4_04_04.mp3"}]}], "check": {"q": "홈즈는 왜 라이더를 경찰에 넘기지 않고 보내 줬나요?", "a": "라이더가 호너에게 불리한 말을 하지 않으면 호너에게 죄를 묻기 어려워져요. 라이더는 너무 겁에 질려서 다시는 나쁜 짓을 못 할 거라고 봤어요. 그리고 크리스마스는 용서하는 때라고 했어요."}, "imgs": [{"at": 1, "src": "img/c6_d.svg"}]}], "solve": {"after": 2, "intro": ["여기서 잠깐 멈춰요. 단서 수첩을 펼쳐서 4장부터 모은 단서를 다시 읽어 보세요. 그리고 홈즈보다 먼저 답을 골라 봐요. 고른 답은 저장해 두었다가, 이 장을 끝까지 읽은 뒤에 맞춰 봐요."], "qs": [{"q": "이 작은 남자는 누구일까요? (Who is the little man?)", "opts": ["① 모자 주인 헨리 베이커 (Henry Baker)", "② 제복 입은 피터슨 (Peterson)", "③ 배관공 존 호너 (John Horner)", "④ 호텔 직원 제임스 라이더 (James Ryder)"]}, {"q": "보석은 어떻게 거위 속에 들어갔을까요? (How did the stone get into the goose?)", "opts": ["① 호텔 부엌에 있던 거위가, 바닥에 떨어진 보석을 우연히 삼켰어요.", "② 헨리 베이커가 보석을 숨기려고, 크리스마스 거위 속에 넣었어요.", "③ 보석을 훔친 사람이 거위에게 삼키게 했는데, 그 거위가 다른 거위와 섞였어요.", "④ 시장 상인 브레킨리지가, 거위를 알파 인에 팔기 전에 넣었어요."]}]}, "solve_answers": [{"answer": "④", "label": "호텔 직원 제임스 라이더", "why": "홈즈가 진짜 이름을 묻자 작은 남자는 처음에 \"John Robinson\"이라는 가짜 이름을 댔다가 \"James Ryder\"라고 털어놔요. 5장 신문 기사에서 호너를 백작부인 방에 데려가고, 보석 상자가 빈 걸 보고 사람들을 부른 그 호텔 직원이에요. ③ 호너는 잡혀가 있었고, ① 헨리 베이커는 보석을 전혀 몰랐어요."}, {"answer": "③", "label": "훔친 사람이 거위에게 삼키게 했는데, 거위가 섞였어요", "why": "라이더는 누이 오크쇼트 부인의 집에서 \"He pushed the stone down a goose's throat.\"라고 털어놔요. 그런데 거위가 도망갔고, \"There were two white geese with a black bar on the tail. Ryder took the wrong one.\" 보석을 삼킨 거위는 브레킨리지와 알파 인을 거쳐 헨리 베이커에게 갔어요."}], "clues": [{"ko": "거위가 지나간 길: 오크쇼트 부인(브릭스턴 로드) → 브레킨리지(시장) → 알파 인 → 헨리 베이커", "en": "Mrs. Oakshott → Breckinridge → the Alpha Inn → Henry Baker"}, {"ko": "브레킨리지는 그 거위들을 자꾸 묻는 사람이 있어서 화가 나 있었어요.", "en": "Everyone keeps asking Breckinridge about those geese."}, {"ko": "작은 남자는 \"그중 한 마리는 내 것\"이라고 했어요. 오크쇼트 부인이 브레킨리지에게 물어보라고 했대요.", "en": "The little man said, \"One of them was mine.\" Mrs. Oakshott told him to ask Breckinridge."}], "clue_intro": "오늘 읽은 내용에서 이 세 가지를 수첩에 적어 두세요. 「직접 풀어 보기」에서 쓸 거예요.", "quiz": [{"q": "Where did Breckinridge get the Alpha's geese?", "ko": "브레킨리지는 알파 인에 판 거위를 어디서 샀나요?", "opts": ["① from Henry Baker", "② from a farm in the country", "③ from the Hotel Cosmopolitan", "④ from Mrs. Oakshott in Brixton Road"], "answer": "④", "why": "장부에 \"Mrs. Oakshott, 117 Brixton Road. December 22nd. Twenty-four geese. Sold to the Alpha.\"라고 적혀 있어요. 브레킨리지도 \"It came from the town!\"이라고 해요. 그래서 ②는 틀려요."}, {"q": "How did Holmes get the facts from Breckinridge?", "ko": "홈즈는 어떻게 브레킨리지에게서 사실을 알아냈나요?", "opts": ["① He gave him a goose.", "② He made a bet with him.", "③ He called the police.", "④ He read a newspaper."], "answer": "②", "why": "홈즈가 \"If you want facts from a man like that, make a bet with him.\"이라고 말해요. 그냥 물었을 때는 \"I won't tell you!\"라고 했어요."}, {"q": "Why did Ryder take the wrong goose?", "ko": "라이더는 왜 엉뚱한 거위를 가져갔나요?", "opts": ["① His sister hid the right goose.", "② It was too dark to see.", "③ There were two white geese with a black bar on the tail.", "④ The right goose was too heavy."], "answer": "③", "why": "\"There were two white geese with a black bar on the tail. Ryder took the wrong one.\" 꼬리에 검은 줄이 있는 흰 거위가 두 마리라 헷갈렸어요."}, {"q": "\"Besides, it is the season of forgiveness.\" What does forgiveness mean?", "ko": "여기서 forgiveness는 무슨 뜻일까요?", "opts": ["① not punishing someone for a bad thing", "② a big Christmas dinner", "③ a cold winter night", "④ a present for a friend"], "answer": "①", "why": "홈즈는 바로 앞에서 문을 열고 \"Get out!\"이라며 라이더를 경찰에 넘기지 않고 보내 줬어요. 잘못한 사람을 벌주지 않고 봐주는 것을 용서라고 해요. 크리스마스 무렵이라 \"season(때, 철)\"이라고 했어요."}], "record": [{"t": "Will you bet on it?", "src": "audio/c6_r0.mp3", "sp": "Breckinridge"}, {"t": "No, no. The real name.", "src": "audio/c6_r1.mp3", "sp": "Holmes"}, {"t": "Besides, it is the season of forgiveness.", "src": "audio/c6_r2.mp3", "sp": "Holmes"}], "think": "홈즈는 보석을 훔친 라이더를 경찰에 넘기지 않고 보내 줬어요. 홈즈가 잘한 걸까요? 여러분 생각을 한두 줄로 써 봐요. 정답은 없어요. 예: \"나는 ___라고 생각해요. 왜냐하면 ___.\"", "reflect": null, "cert": null, "end": null, "words_read": 398}, "7": {"n": 7, "label": "7장", "title_en": "The Missing Horse", "title_ko": "사라진 우승 후보", "new_text": false, "source": "원작: 아서 코난 도일, 「실버 블레이즈(Silver Blaze)」, 『셜록 홈즈의 회상록』(Project Gutenberg #834, 67~408행). 초6 눈높이(CEFR A2~B1 초반)로 쉽게 고쳐 쓴 글이에요.", "recap_title": "새 사건 소개", "recap": ["푸른 석류석 사건은 크리스마스의 용서로 끝났어요. 이번에는 영국에서 가장 유명한 경주마가 큰 경주를 앞두고 감쪽같이 사라졌어요. 그 말을 돌보던 조련사는 마구간 근처 우묵한 곳에서 숨진 채 발견됐어요. 홈즈와 왓슨은 기차를 타고 다트무어로 가요. 마지막 사건이에요."], "cards": [{"en": "Sherlock Holmes", "ko": "셜록 홈즈", "new": false, "line": "런던 베이커 가 221B에 사는 탐정이에요. 낡은 모자로 주인을 알아내고, 거위가 온 길을 따라가 보석 도둑을 찾았어요.", "img": "img/p_holmes.jpg"}, {"en": "Watson", "ko": "왓슨", "new": false, "line": "의사이고 홈즈의 친구예요. 이 이야기를 들려주는 '나(I)'예요. 기차 안에서 홈즈에게 사건 이야기를 들어요.", "img": "img/p_watson.jpg"}, {"en": "Silver Blaze", "ko": "실버 블레이즈", "new": true, "line": "영국에서 가장 유명한 경주마예요. 곧 열리는 웨섹스 컵 경주의 우승 후보예요. 경주를 며칠 앞두고 사라졌어요.", "img": "img/p_silverblaze.svg"}, {"en": "John Straker", "ko": "존 스트레이커", "new": true, "line": "실버 블레이즈를 돌보던 조련사예요. 한밤중에 말이 걱정된다며 마구간에 갔다가, 다음 날 아침 숨진 채 발견됐어요.", "img": "img/p_straker.svg"}, {"en": "Colonel Ross", "ko": "로스 대령", "new": true, "line": "실버 블레이즈의 주인이에요. 1장의 던컨 로스와는 다른 사람이에요.", "img": "img/p_colonelross.svg"}, {"en": "Silas Brown", "ko": "사일러스 브라운", "new": true, "line": "2마일 떨어진 다른 마구간, 메이플턴의 조련사예요.", "img": "img/p_silasbrown.svg"}, {"en": "Ned Hunter", "ko": "네드 헌터", "new": true, "line": "마구간을 지키던 소년이에요. 그날 밤 저녁으로 카레를 먹고 깊이 잠들어 버렸어요.", "img": "img/p_hunter.svg"}, {"en": "Fitzroy Simpson", "ko": "피츠로이 심슨", "new": true, "line": "그날 밤 마구간에 찾아온 낯선 남자예요. 경찰에게 잡혀갔어요. 자기는 말에 대해 알아보러 왔을 뿐이라고 해요.", "img": "img/p_simpson.svg"}], "words": [{"w": "favourite", "ko": "우승 후보", "ex": "Silver Blaze is the favourite for the Wessex Cup.", "why": "'가장 좋아하는'이 아니라 '이길 것 같은 말'이라는 뜻이에요.", "src": "audio/w_favourite.mp3", "exsrc": "audio/c7_v0.mp3"}, {"w": "trainer", "ko": "조련사", "ex": "And his trainer, John Straker, was dead.", "why": "말을 돌보고 훈련시키는 사람이에요.", "src": "audio/w_trainer.mp3", "exsrc": "audio/c7_v1.mp3"}, {"w": "stable", "ko": "마구간", "ex": "On Monday night, the stable was locked at nine.", "why": "말이 사라진 곳이에요.", "src": "audio/w_stable.mp3", "exsrc": "audio/c7_v2.mp3"}, {"w": "guard", "ko": "지키다", "ex": "A boy, Ned Hunter, stayed inside to guard the horses.", "why": "지키던 소년이 왜 잠들었는지가 중요해요.", "src": "audio/w_guard.mp3", "exsrc": "audio/c7_v3.mp3"}, {"w": "drug", "ko": "약", "ex": "Someone had put a drug in Hunter's curry.", "why": "헌터가 깊이 잠든 까닭이에요. 꼭 기억해 두세요.", "src": "audio/w_drug.mp3", "exsrc": "audio/c7_v4.mp3"}, {"w": "curry", "ko": "카레", "ex": "A maid carried his supper to him. It was curry.", "why": "그날 저녁 메뉴예요. 꼭 기억해 두세요.", "src": "audio/w_curry.mp3", "exsrc": "audio/c7_v5.mp3"}, {"w": "tie", "ko": "넥타이", "ex": "In the other, he held the stranger's tie.", "why": "스트레이커 손에 있던 물건이에요.", "src": "audio/w_tie.mp3", "exsrc": "audio/c7_v6.mp3"}, {"w": "hollow", "ko": "우묵한 곳", "ex": "Near it, in a hollow, they found Straker.", "why": "3장의 hollow(속이 빈)와 뜻이 달라요. 여기서는 땅이 움푹 꺼진 곳이에요.", "src": "audio/w_hollow.mp3", "exsrc": "audio/c7_v7.mp3"}], "scenes": [{"no": 1, "title": "다트무어로 가는 기차", "paras": [{"kind": "p", "units": [{"t": "One morning at breakfast, Holmes said,", "sp": "Watson", "src": "audio/c7_1_00_00.mp3"}, {"t": "\"I must go to Dartmoor, Watson.\"", "sp": "Holmes", "src": "audio/c7_1_00_01.mp3"}]}, {"kind": "p", "units": [{"t": "I knew why.", "sp": "Watson", "src": "audio/c7_1_01_00.mp3"}, {"t": "All of England was talking about one case.", "sp": "Watson", "src": "audio/c7_1_01_01.mp3"}, {"t": "Silver Blaze, the most famous racehorse in England, had disappeared.", "sp": "Watson", "src": "audio/c7_1_01_02.mp3"}, {"t": "And his trainer, John Straker, was dead.", "sp": "Watson", "src": "audio/c7_1_01_03.mp3"}]}, {"kind": "p", "units": [{"t": "On the train, Holmes told me the facts.", "sp": "Watson", "src": "audio/c7_1_02_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"Silver Blaze is the favourite for the Wessex Cup.", "sp": "Holmes", "src": "audio/c7_1_03_00.mp3"}, {"t": "Everyone thinks he will win.", "sp": "Holmes", "src": "audio/c7_1_03_01.mp3"}, {"t": "So some people did not want him in the race.", "sp": "Holmes", "src": "audio/c7_1_03_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"His owner is Colonel Ross.", "sp": "Holmes", "src": "audio/c7_1_04_00.mp3"}, {"t": "The horse lives at King's Pyland.", "sp": "Holmes", "src": "audio/c7_1_04_01.mp3"}, {"t": "Two miles away, there is another stable, Mapleton.", "sp": "Holmes", "src": "audio/c7_1_04_02.mp3"}, {"t": "Its trainer is Silas Brown.", "sp": "Holmes", "src": "audio/c7_1_04_03.mp3"}]}], "check": {"q": "실버 블레이즈는 어떤 말인가요?", "a": "영국에서 가장 유명한 경주마이고, 웨섹스 컵 경주의 우승 후보예요. 모두 이 말이 이길 거라고 생각해서, 이 말이 경주에 못 나오기를 바라는 사람도 있었어요."}, "imgs": [{"at": 2, "src": "img/c7_a.svg"}]}, {"no": 2, "title": "마구간에 온 낯선 남자", "paras": [{"kind": "p", "units": [{"t": "\"On Monday night, the stable was locked at nine.", "sp": "Holmes", "src": "audio/c7_2_00_00.mp3"}, {"t": "A boy, Ned Hunter, stayed inside to guard the horses.", "sp": "Holmes", "src": "audio/c7_2_00_01.mp3"}, {"t": "A maid carried his supper to him.", "sp": "Holmes", "src": "audio/c7_2_00_02.mp3"}, {"t": "It was curry.", "sp": "Holmes", "src": "audio/c7_2_00_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"On the way, a stranger stopped her.", "sp": "Holmes", "src": "audio/c7_2_01_00.mp3"}, {"t": "He wore a grey suit and carried a heavy stick.", "sp": "Holmes", "src": "audio/c7_2_01_01.mp3"}, {"t": "'Give this paper to the boy,'", "sp": "Simpson", "src": "audio/c7_2_01_02.mp3"}, {"t": "he said.", "sp": "Holmes", "src": "audio/c7_2_01_03.mp3"}, {"t": "'You will get a pretty new dress.'", "sp": "Simpson", "src": "audio/c7_2_01_04.mp3"}]}, {"kind": "p", "units": [{"t": "\"She was frightened and ran to the stable window.", "sp": "Holmes", "src": "audio/c7_2_02_00.mp3"}, {"t": "The stranger came after her.", "sp": "Holmes", "src": "audio/c7_2_02_01.mp3"}, {"t": "Hunter ran to let the dog loose.", "sp": "Holmes", "src": "audio/c7_2_02_02.mp3"}, {"t": "When he came out with the dog, the man was gone.\"", "sp": "Holmes", "src": "audio/c7_2_02_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"Did the boy leave the door open?\"", "sp": "Watson", "src": "audio/c7_2_03_00.mp3"}, {"t": "I asked.", "sp": "Watson", "src": "audio/c7_2_03_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Excellent, Watson!", "sp": "Holmes", "src": "audio/c7_2_04_00.mp3"}, {"t": "No, he locked the door behind him.", "sp": "Holmes", "src": "audio/c7_2_04_01.mp3"}]}], "check": {"q": "헌터는 낯선 남자를 쫓아내려고 무엇을 했나요?", "a": "마구간에 있던 개를 풀어 데리고 나갔어요. 나가면서 문은 잠갔고요. 개를 데리고 나와 보니 남자는 벌써 사라지고 없었어요."}, "imgs": [{"at": 0, "src": "img/c7_b.svg"}]}, {"no": 3, "title": "비 오는 밤", "paras": [{"kind": "p", "units": [{"t": "\"Straker heard about the stranger.", "sp": "Holmes", "src": "audio/c7_3_00_00.mp3"}, {"t": "At one in the morning, he got up.", "sp": "Holmes", "src": "audio/c7_3_00_01.mp3"}, {"t": "'I'm worried about the horses,'", "sp": "Straker", "src": "audio/c7_3_00_02.mp3"}, {"t": "he said.", "sp": "Holmes", "src": "audio/c7_3_00_03.mp3"}, {"t": "He went out to the stable in the rain.", "sp": "Holmes", "src": "audio/c7_3_00_04.mp3"}]}, {"kind": "p", "units": [{"t": "\"In the morning, he had not come back.", "sp": "Holmes", "src": "audio/c7_3_01_00.mp3"}, {"t": "The stable door was open.", "sp": "Holmes", "src": "audio/c7_3_01_01.mp3"}, {"t": "Hunter was in a deep sleep, and Silver Blaze was gone!", "sp": "Holmes", "src": "audio/c7_3_01_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"Not far away, Straker's coat hung on a bush.", "sp": "Holmes", "src": "audio/c7_3_02_00.mp3"}, {"t": "Near it, in a hollow, they found Straker.", "sp": "Holmes", "src": "audio/c7_3_02_01.mp3"}, {"t": "He was dead.", "sp": "Holmes", "src": "audio/c7_3_02_02.mp3"}, {"t": "In one hand, he held a small knife.", "sp": "Holmes", "src": "audio/c7_3_02_03.mp3"}, {"t": "In the other, he held the stranger's tie.", "sp": "Holmes", "src": "audio/c7_3_02_04.mp3"}]}, {"kind": "p", "units": [{"t": "\"Someone had put a drug in Hunter's curry.", "sp": "Holmes", "src": "audio/c7_3_03_00.mp3"}, {"t": "But the people at the house ate the same curry, and they were fine.", "sp": "Holmes", "src": "audio/c7_3_03_01.mp3"}]}], "check": {"q": "헌터는 왜 아침까지 깨어나지 못했나요?", "a": "누군가 헌터의 저녁 카레에 약을 넣었기 때문이에요. 그런데 집에 있던 사람들은 같은 카레를 먹고도 아무렇지 않았어요."}, "imgs": [{"at": 1, "src": "img/c7_c.svg"}]}, {"no": 4, "title": "잡혀간 낯선 남자", "paras": [{"kind": "p", "units": [{"t": "\"The police caught the stranger.", "sp": "Holmes", "src": "audio/c7_4_00_00.mp3"}, {"t": "His name is Fitzroy Simpson.", "sp": "Holmes", "src": "audio/c7_4_00_01.mp3"}, {"t": "He said he only wanted some facts about the horses.", "sp": "Holmes", "src": "audio/c7_4_00_02.mp3"}, {"t": "But the tie was his.", "sp": "Holmes", "src": "audio/c7_4_00_03.mp3"}, {"t": "His clothes were wet from the rain that night.", "sp": "Holmes", "src": "audio/c7_4_00_04.mp3"}, {"t": "And he had a heavy stick.\"", "sp": "Holmes", "src": "audio/c7_4_00_05.mp3"}]}, {"kind": "p", "units": [{"t": "\"What do the police think?\"", "sp": "Watson", "src": "audio/c7_4_01_00.mp3"}, {"t": "I asked.", "sp": "Watson", "src": "audio/c7_4_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Every idea has problems,\"", "sp": "Holmes", "src": "audio/c7_4_02_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c7_4_02_01.mp3"}, {"t": "\"The police think Simpson took the horse out.", "sp": "Holmes", "src": "audio/c7_4_02_02.mp3"}, {"t": "Then Straker found him, and they had a fight.", "sp": "Holmes", "src": "audio/c7_4_02_03.mp3"}, {"t": "I will see for myself when I get there.\"", "sp": "Holmes", "src": "audio/c7_4_02_04.mp3"}]}], "check": {"q": "경찰은 왜 심슨을 의심하나요?", "a": "스트레이커가 쥐고 있던 넥타이가 심슨의 것이고, 그날 밤 비에 젖은 옷을 입고 있었고, 무거운 지팡이도 가지고 있었기 때문이에요. 하지만 홈즈는 경찰 생각에 문제가 있다고 해요."}, "imgs": []}], "solve": null, "solve_answers": [], "clues": [{"ko": "마구간 소년의 저녁은 카레였고, 그 카레에 약이 들어 있었어요. 집에 있던 사람들은 같은 카레를 먹고도 괜찮았어요.", "en": "Hunter's supper was curry, and there was a drug in it. The people at the house ate the same curry and were fine."}, {"ko": "마구간에는 개가 있어요. 헌터는 낯선 남자를 쫓아내려고 그 개를 풀었어요.", "en": "There is a dog in the stable. Hunter let it loose when the stranger came."}, {"ko": "스트레이커는 새벽 1시에 말이 걱정된다며 빗속에 마구간으로 나갔어요. 발견됐을 때 한 손에는 작은 칼, 다른 손에는 낯선 남자의 넥타이를 쥐고 있었어요.", "en": "Straker went out to the stable at one in the morning. He held a small knife and the stranger's tie."}], "clue_intro": "오늘 읽은 내용에서 이 세 가지를 수첩에 적어 두세요.", "quiz": [{"q": "What did the maid carry to the stable?", "ko": "하녀는 마구간에 무엇을 가져갔나요?", "opts": ["① a new dress", "② Hunter's supper of curry", "③ a letter from Colonel Ross", "④ a heavy stick"], "answer": "②", "why": "\"A maid carried his supper to him. It was curry.\"라고 나와요. ① 새 옷은 낯선 남자가 주겠다고 한 거예요."}, {"q": "What did Hunter do when the stranger came to the window?", "ko": "낯선 남자가 창문으로 왔을 때 헌터는 무엇을 했나요?", "opts": ["① He ate his supper.", "② He opened the door for him.", "③ He fell asleep.", "④ He ran to let the dog loose."], "answer": "④", "why": "\"Hunter ran to let the dog loose.\"라고 나와요. 문은 열어 두지 않았어요. 홈즈가 \"He locked the door behind him.\"이라고 해요."}, {"q": "Why do the police think that Simpson is guilty?", "ko": "경찰은 왜 심슨이 범인이라고 생각하나요?", "opts": ["① His tie was in Straker's hand, and his clothes were wet.", "② He was the trainer of Mapleton.", "③ He ate the same curry.", "④ He was Straker's friend."], "answer": "①", "why": "\"But the tie was his.\"라고 나와요. 그날 밤 비에 젖은 옷(His clothes were wet from the rain that night)과 무거운 지팡이(a heavy stick)도 있었어요. ② 메이플턴의 조련사는 사일러스 브라운이에요."}, {"q": "\"A boy, Ned Hunter, stayed inside to guard the horses.\" What does guard mean?", "ko": "여기서 guard는 무슨 뜻일까요?", "opts": ["① to keep safe", "② to sell", "③ to feed", "④ to ride"], "answer": "①", "why": "헌터는 밤새 마구간 안에서 말들을 지키는 소년이에요. 낯선 남자가 오자 개를 풀어 쫓아내려고 한 것도 그래서예요."}], "record": [{"t": "I must go to Dartmoor, Watson.", "src": "audio/c7_r0.mp3", "sp": "Holmes"}, {"t": "Excellent, Watson!", "src": "audio/c7_r1.mp3", "sp": "Holmes"}, {"t": "I will see for myself when I get there.", "src": "audio/c7_r2.mp3", "sp": "Holmes"}], "think": "", "reflect": null, "cert": null, "end": null, "words_read": 397}, "8": {"n": 8, "label": "8장", "title_en": "What Was in His Pockets", "title_ko": "주머니 속 물건들", "new_text": false, "source": "원작: 아서 코난 도일, 「실버 블레이즈(Silver Blaze)」, 『셜록 홈즈의 회상록』(Project Gutenberg #834, 410~682행). 초6 눈높이(CEFR A2~B1 초반)로 쉽게 고쳐 쓴 글이에요.", "recap_title": "지난 이야기", "recap": ["경주마 실버 블레이즈가 사라졌고, 조련사 스트레이커는 마구간 근처 우묵한 곳에서 숨진 채 발견됐어요. 그날 밤 마구간 소년의 카레에는 약이 들어 있었어요. 경찰은 스트레이커가 넥타이를 쥐고 있던 낯선 남자 심슨을 잡았지만, 홈즈는 경찰 생각에 문제가 있다고 해요."], "cards": [{"en": "Sherlock Holmes", "ko": "셜록 홈즈", "new": false, "line": "런던 베이커 가 221B에 사는 탐정이에요. 다트무어에 직접 와서 사건을 살펴요.", "img": "img/p_holmes.jpg"}, {"en": "Watson", "ko": "왓슨", "new": false, "line": "의사이고 홈즈의 친구예요. 이 이야기를 들려주는 '나(I)'예요.", "img": "img/p_watson.jpg"}, {"en": "Colonel Ross", "ko": "로스 대령", "new": false, "line": "실버 블레이즈의 주인이에요. 말을 되찾고 싶어 해요.", "img": "img/p_colonelross.svg"}, {"en": "Inspector Gregory", "ko": "그레고리 경감", "new": true, "line": "이 사건을 맡은 경찰이에요. 심슨이 범인이라고 생각해요.", "img": "img/p_gregory.svg"}, {"en": "Mrs. Straker", "ko": "스트레이커 부인", "new": true, "line": "숨진 조련사 존 스트레이커의 아내예요.", "img": "img/p_mrsstraker.svg"}, {"en": "John Straker", "ko": "존 스트레이커", "new": false, "line": "실버 블레이즈의 조련사예요. 한밤중에 마구간에 갔다가 숨진 채 발견됐어요. 손에 작은 칼을 쥐고 있었어요.", "img": "img/p_straker.svg"}], "words": [{"w": "fine", "ko": "섬세한, 아주 가는", "ex": "A very fine knife for very fine work.", "why": "여기서 fine은 '좋은'이 아니라 '아주 섬세한'이라는 뜻이에요.", "src": "audio/w_fine.mp3", "exsrc": "audio/c8_v0.mp3"}, {"w": "moor", "ko": "황무지", "ex": "A strange thing to take onto the moor at night.", "why": "다트무어의 넓고 거친 들판이에요. 사건이 일어난 곳이에요.", "src": "audio/w_moor.mp3", "exsrc": "audio/c8_v1.mp3"}, {"w": "knife", "ko": "칼", "ex": "There were also a pipe, a watch, some papers and a very thin knife.", "why": "아주 얇은 칼이 왜 주머니에 있었을까요?", "src": "audio/w_knife.mp3", "exsrc": "audio/c8_v2.mp3"}, {"w": "operation", "ko": "수술", "ex": "It is a knife for eye operations.", "why": "의사인 왓슨이 칼을 알아봤어요.", "src": "audio/w_operation.mp3", "exsrc": "audio/c8_v3.mp3"}, {"w": "bill", "ko": "청구서, 계산서", "ex": "One paper was a bill for an expensive dress.", "why": "누구의 옷값인지가 중요해요.", "src": "audio/w_bill.mp3", "exsrc": "audio/c8_v4.mp3"}, {"w": "dress", "ko": "옷, 드레스", "ex": "I never had such a dress, sir.", "why": "스트레이커 부인의 이 말에 홈즈가 \"이제 확실해졌어요\"라고 했어요.", "src": "audio/w_dress.mp3", "exsrc": "audio/c8_v5.mp3"}, {"w": "wind", "ko": "바람", "ex": "There was no wind that night?", "why": "바람이 없었으니 코트는 누가 걸쳐 둔 거예요.", "src": "audio/w_wind.mp3", "exsrc": "audio/c8_v6.mp3"}, {"w": "match", "ko": "성냥", "ex": "It was a half-burned match.", "why": "홈즈가 진흙 속에서 찾은 거예요. 찾을 줄 알았대요.", "src": "audio/w_match.mp3", "exsrc": "audio/c8_v7.mp3"}], "scenes": [{"no": 1, "title": "다트무어에 도착하다", "paras": [{"kind": "p", "units": [{"t": "In the evening, we reached Tavistock.", "sp": "Watson", "src": "audio/c8_1_00_00.mp3"}, {"t": "Colonel Ross and Inspector Gregory met us at the station.", "sp": "Watson", "src": "audio/c8_1_00_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"I want my horse back, Mr. Holmes,\"", "sp": "Colonel", "src": "audio/c8_1_01_00.mp3"}, {"t": "said the Colonel.", "sp": "Watson", "src": "audio/c8_1_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "In the carriage, Gregory said,", "sp": "Watson", "src": "audio/c8_1_02_00.mp3"}, {"t": "\"I believe Simpson is our man.\"", "sp": "Gregory", "src": "audio/c8_1_02_01.mp3"}]}, {"kind": "p", "units": [{"t": "Holmes shook his head.", "sp": "Watson", "src": "audio/c8_1_03_00.mp3"}, {"t": "\"Why would he take the horse out of the stable?", "sp": "Holmes", "src": "audio/c8_1_03_01.mp3"}, {"t": "And where could a stranger hide such a horse?\"", "sp": "Holmes", "src": "audio/c8_1_03_02.mp3"}]}, {"kind": "p", "units": [{"t": "Then we reached Straker's house.", "sp": "Watson", "src": "audio/c8_1_04_00.mp3"}, {"t": "Everyone got out, but Holmes sat still and stared at the sky.", "sp": "Watson", "src": "audio/c8_1_04_01.mp3"}, {"t": "When I touched his arm, he jumped.", "sp": "Watson", "src": "audio/c8_1_04_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"Excuse me.", "sp": "Holmes", "src": "audio/c8_1_05_00.mp3"}, {"t": "I was dreaming,\"", "sp": "Holmes", "src": "audio/c8_1_05_01.mp3"}, {"t": "he said.", "sp": "Watson", "src": "audio/c8_1_05_02.mp3"}, {"t": "But his eyes were shining.", "sp": "Watson", "src": "audio/c8_1_05_03.mp3"}, {"t": "I knew that he had found a clue.", "sp": "Watson", "src": "audio/c8_1_05_04.mp3"}]}], "check": {"q": "마차에서 내리지 않고 하늘만 보던 홈즈의 눈은 어땠나요?", "a": "반짝이고 있었어요. 왓슨은 홈즈가 단서를 찾았다는 걸 알아챘어요. 하지만 홈즈는 그게 무엇인지 아직 말하지 않아요."}, "imgs": [{"at": 0, "src": "img/c8_a.svg"}]}, {"no": 2, "title": "주머니 속 물건들", "paras": [{"kind": "p", "units": [{"t": "The Inspector showed us the things from Straker's pockets.", "sp": "Watson", "src": "audio/c8_2_00_00.mp3"}, {"t": "There were matches and a short candle.", "sp": "Watson", "src": "audio/c8_2_00_01.mp3"}, {"t": "There were also a pipe, a watch, some papers and a very thin knife.", "sp": "Watson", "src": "audio/c8_2_00_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"This is a strange knife,\"", "sp": "Holmes", "src": "audio/c8_2_01_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c8_2_01_01.mp3"}, {"t": "\"Watson, you are a doctor.\"", "sp": "Holmes", "src": "audio/c8_2_01_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"It is a knife for eye operations,\"", "sp": "Watson", "src": "audio/c8_2_02_00.mp3"}, {"t": "I said.", "sp": "Watson", "src": "audio/c8_2_02_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"A very fine knife for very fine work,\"", "sp": "Holmes", "src": "audio/c8_2_03_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c8_2_03_01.mp3"}, {"t": "\"A strange thing to take onto the moor at night.\"", "sp": "Holmes", "src": "audio/c8_2_03_02.mp3"}]}, {"kind": "p", "units": [{"t": "One paper was a bill for an expensive dress.", "sp": "Watson", "src": "audio/c8_2_04_00.mp3"}, {"t": "It was for a man called William Derbyshire.", "sp": "Watson", "src": "audio/c8_2_04_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Mrs. Straker says Derbyshire was her husband's friend,\"", "sp": "Gregory", "src": "audio/c8_2_05_00.mp3"}, {"t": "said the Inspector.", "sp": "Watson", "src": "audio/c8_2_05_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"That is a lot of money for one dress,\"", "sp": "Holmes", "src": "audio/c8_2_06_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c8_2_06_01.mp3"}]}], "check": {"q": "스트레이커의 주머니에서 나온 칼은 어떤 칼인가요?", "a": "의사 왓슨이 알아본 대로 눈 수술에 쓰는 아주 얇고 섬세한 칼이에요. 홈즈는 밤에 황무지에 들고 가기에는 이상한 물건이라고 했어요."}, "imgs": [{"at": 0, "src": "img/c8_b.svg"}]}, {"no": 3, "title": "그런 옷은 없어요", "paras": [{"kind": "p", "units": [{"t": "As we left, Mrs. Straker came up to us.", "sp": "Watson", "src": "audio/c8_3_00_00.mp3"}, {"t": "\"Have you found the men?\"", "sp": "MrsStraker", "src": "audio/c8_3_00_01.mp3"}, {"t": "she asked.", "sp": "Watson", "src": "audio/c8_3_00_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"Surely I met you at a party in Plymouth, Mrs. Straker?\"", "sp": "Holmes", "src": "audio/c8_3_01_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c8_3_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"No, sir.", "sp": "MrsStraker", "src": "audio/c8_3_02_00.mp3"}, {"t": "You are wrong.\"", "sp": "MrsStraker", "src": "audio/c8_3_02_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"But I am sure of it.", "sp": "Holmes", "src": "audio/c8_3_03_00.mp3"}, {"t": "You wore a dress of grey silk with feathers.\"", "sp": "Holmes", "src": "audio/c8_3_03_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"I never had such a dress, sir.\"", "sp": "MrsStraker", "src": "audio/c8_3_04_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"Ah, that settles it,\"", "sp": "Holmes", "src": "audio/c8_3_05_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c8_3_05_01.mp3"}]}], "check": {"q": "스트레이커 부인은 회색 비단 옷에 대해 뭐라고 했나요?", "a": "그런 옷은 가져 본 적이 없다고 했어요. 홈즈는 그 말을 듣고 \"이제 확실해졌어요(that settles it)\"라고 했어요. 홈즈가 왜 이런 걸 물었는지 생각해 봐요."}, "imgs": []}, {"no": 4, "title": "진흙 속의 성냥", "paras": [{"kind": "p", "units": [{"t": "We walked to the hollow.", "sp": "Watson", "src": "audio/c8_4_00_00.mp3"}, {"t": "Straker's coat had hung on a bush there.", "sp": "Watson", "src": "audio/c8_4_00_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"There was no wind that night?\"", "sp": "Holmes", "src": "audio/c8_4_01_00.mp3"}, {"t": "asked Holmes.", "sp": "Watson", "src": "audio/c8_4_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"No, but very heavy rain.\"", "sp": "Gregory", "src": "audio/c8_4_02_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"Then the coat did not blow onto the bush.", "sp": "Holmes", "src": "audio/c8_4_03_00.mp3"}, {"t": "Someone put it there.\"", "sp": "Holmes", "src": "audio/c8_4_03_01.mp3"}]}, {"kind": "p", "units": [{"t": "Holmes lay down on his face and looked at the mud.", "sp": "Watson", "src": "audio/c8_4_04_00.mp3"}, {"t": "\"Hullo!", "sp": "Holmes", "src": "audio/c8_4_04_01.mp3"}, {"t": "What's this?\"", "sp": "Holmes", "src": "audio/c8_4_04_02.mp3"}, {"t": "It was a half-burned match.", "sp": "Watson", "src": "audio/c8_4_04_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"I didn't see it,\"", "sp": "Gregory", "src": "audio/c8_4_05_00.mp3"}, {"t": "said the Inspector.", "sp": "Watson", "src": "audio/c8_4_05_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"I only saw it because I was looking for it,\"", "sp": "Holmes", "src": "audio/c8_4_06_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c8_4_06_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"You expected to find it?\"", "sp": "Gregory", "src": "audio/c8_4_07_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"I thought it was likely.\"", "sp": "Holmes", "src": "audio/c8_4_08_00.mp3"}, {"t": "Then Holmes put one of Silver Blaze's horseshoes in his pocket.", "sp": "Watson", "src": "audio/c8_4_08_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Should we take my horse out of the race?\"", "sp": "Colonel", "src": "audio/c8_4_09_00.mp3"}, {"t": "the Colonel asked the Inspector.", "sp": "Watson", "src": "audio/c8_4_09_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Certainly not,\"", "sp": "Holmes", "src": "audio/c8_4_10_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c8_4_10_01.mp3"}, {"t": "\"Let his name stay in.\"", "sp": "Holmes", "src": "audio/c8_4_10_02.mp3"}]}], "check": {"q": "홈즈는 왜 스트레이커의 코트를 누가 일부러 덤불에 걸쳐 두었다고 했나요?", "a": "그날 밤에는 바람이 없었어요. 바람에 날려 간 게 아니라면, 누군가 일부러 걸쳐 둔 거예요."}, "imgs": [{"at": 4, "src": "img/c8_c.svg"}]}], "solve": null, "solve_answers": [], "clues": [{"ko": "스트레이커의 주머니에는 성냥, 양초, 그리고 눈 수술에 쓰는 아주 얇은 칼이 있었어요.", "en": "Straker had matches, a candle and a very thin knife for eye operations."}, {"ko": "윌리엄 더비셔라는 사람 앞으로 된 비싼 옷값 청구서가 있었어요. 홈즈가 회색 비단 옷 이야기를 꺼내자, 스트레이커 부인은 그런 옷을 가져 본 적이 없다고 했어요.", "en": "There was a bill for an expensive dress for William Derbyshire. Mrs. Straker never had a grey silk dress."}, {"ko": "바람이 없던 밤인데 코트가 덤불에 걸쳐져 있었어요. 진흙 속에는 반쯤 탄 성냥이 있었어요.", "en": "There was no wind, so someone put the coat on the bush. There was a half-burned match in the mud."}], "clue_intro": "오늘 읽은 내용에서 이 세 가지를 수첩에 적어 두세요.", "quiz": [{"q": "What kind of knife was in Straker's pocket?", "ko": "스트레이커의 주머니에서 나온 칼은 어떤 칼인가요?", "opts": ["① a big kitchen knife", "② a knife for eye operations", "③ a hunting knife", "④ a knife for cutting apples"], "answer": "②", "why": "왓슨이 \"It is a knife for eye operations.\"라고 해요. 홈즈도 \"A very fine knife for very fine work.\"라고 해요."}, {"q": "What did Holmes find in the mud?", "ko": "홈즈는 진흙 속에서 무엇을 찾았나요?", "opts": ["① a horseshoe", "② a red tie", "③ a half-burned match", "④ a key"], "answer": "③", "why": "\"It was a half-burned match.\"라고 나와요. ① 실버 블레이즈의 편자는 홈즈가 주머니에 넣은 것이고, 진흙에서 찾은 게 아니에요."}, {"q": "Why did Holmes say that someone put the coat on the bush?", "ko": "홈즈는 왜 누군가 코트를 덤불에 걸쳐 두었다고 했나요?", "opts": ["① There was no wind that night.", "② The coat was very wet.", "③ The bush was very tall.", "④ Mrs. Straker told him."], "answer": "①", "why": "\"There was no wind that night?\" \"No, but very heavy rain.\" \"Then the coat did not blow onto the bush. Someone put it there.\" 바람이 없었으니 날아갈 수 없었어요."}, {"q": "\"One paper was a bill for an expensive dress.\" What is a bill?", "ko": "여기서 bill은 무엇일까요?", "opts": ["① a letter from a friend", "② a train ticket", "③ a newspaper", "④ a paper that says how much money you must pay"], "answer": "④", "why": "비싼 옷값(an expensive dress)을 얼마 내야 하는지 적힌 종이예요. 그래서 홈즈가 \"That is a lot of money for one dress.\"라고 해요."}], "record": [{"t": "Excuse me. I was dreaming.", "src": "audio/c8_r0.mp3", "sp": "Holmes"}, {"t": "I never had such a dress, sir.", "src": "audio/c8_r1.mp3", "sp": "MrsStraker"}, {"t": "I only saw it because I was looking for it.", "src": "audio/c8_r2.mp3", "sp": "Holmes"}], "think": "", "reflect": null, "cert": null, "end": null, "words_read": 397}, "9": {"n": 9, "label": "9장", "title_en": "The Dog in the Night", "title_ko": "밤중의 개", "new_text": false, "source": "원작: 아서 코난 도일, 「실버 블레이즈(Silver Blaze)」, 『셜록 홈즈의 회상록』(Project Gutenberg #834, 689~958행). 초6 눈높이(CEFR A2~B1 초반)로 쉽게 고쳐 쓴 글이에요.", "recap_title": "지난 이야기", "recap": ["스트레이커의 주머니에서 성냥, 양초, 눈 수술용 얇은 칼, 그리고 더비셔라는 사람 앞으로 된 비싼 옷값 청구서가 나왔어요. 홈즈가 회색 비단 옷 이야기를 꺼내자 스트레이커 부인은 그런 옷을 가져 본 적이 없다고 했어요. 홈즈는 진흙 속에서 반쯤 탄 성냥을 찾았고, 실버 블레이즈의 편자를 주머니에 넣었어요."], "cards": [{"en": "Sherlock Holmes", "ko": "셜록 홈즈", "new": false, "line": "런던 베이커 가 221B에 사는 탐정이에요. 사람이 아니라 말이 어디로 갔는지부터 찾아요.", "img": "img/p_holmes.jpg"}, {"en": "Watson", "ko": "왓슨", "new": false, "line": "의사이고 홈즈의 친구예요. 이 이야기를 들려주는 '나(I)'예요.", "img": "img/p_watson.jpg"}, {"en": "Silas Brown", "ko": "사일러스 브라운", "new": false, "line": "이웃 마구간 메이플턴의 조련사예요. 오늘 처음 만나요. 나이가 많고 사나워 보여요.", "img": "img/p_silasbrown.svg"}, {"en": "Colonel Ross", "ko": "로스 대령", "new": false, "line": "실버 블레이즈의 주인이에요. 홈즈가 아무것도 못 한다고 생각해서 못마땅해해요.", "img": "img/p_colonelross.svg"}, {"en": "Inspector Gregory", "ko": "그레고리 경감", "new": false, "line": "이 사건을 맡은 경찰이에요. 홈즈에게 무엇을 눈여겨봐야 하는지 물어요.", "img": "img/p_gregory.svg"}], "words": [{"w": "track", "ko": "발자국, 자국", "ex": "There was a horse's track.", "why": "홈즈가 말이 간 길을 찾는 방법이에요.", "src": "audio/w_track.mp3", "exsrc": "audio/c9_v0.mp3"}, {"w": "fit", "ko": "꼭 맞다 (fitted)", "ex": "It fitted exactly!", "why": "실버 블레이즈의 편자가 발자국에 꼭 맞았어요.", "src": "audio/w_fit.mp3", "exsrc": "audio/c9_v1.mp3"}, {"w": "alone", "ko": "혼자", "ex": "The horse was alone before!", "why": "처음엔 말 혼자였는데, 나중에 사람 발자국이 붙었어요.", "src": "audio/w_alone.mp3", "exsrc": "audio/c9_v2.mp3"}, {"w": "hide", "ko": "숨기다 (hid)", "ex": "Then he hid him at Mapleton.", "why": "사일러스 브라운이 한 일이에요.", "src": "audio/w_hide.mp3", "exsrc": "audio/c9_v3.mp3"}, {"w": "photograph", "ko": "사진", "ex": "May I have a photograph of Mr. Straker?", "why": "홈즈가 왜 스트레이커 사진을 원했을까요?", "src": "audio/w_photograph.mp3", "exsrc": "audio/c9_v4.mp3"}, {"w": "lame", "ko": "다리를 저는", "ex": "Three of them have gone lame, sir.", "why": "홈즈가 이 말을 듣고 아주 기뻐했어요.", "src": "audio/w_lame.mp3", "exsrc": "audio/c9_v5.mp3"}, {"w": "curious", "ko": "이상한, 묘한", "ex": "That was the curious incident.", "why": "홈즈의 가장 유명한 말 가운데 하나예요.", "src": "audio/w_curious.mp3", "exsrc": "audio/c9_v6.mp3"}], "scenes": [{"no": 1, "title": "말발굽 자국", "paras": [{"kind": "p", "units": [{"t": "\"Let's leave the question of Straker for now,\"", "sp": "Holmes", "src": "audio/c9_1_00_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c9_1_00_01.mp3"}, {"t": "\"Let's find the horse.", "sp": "Holmes", "src": "audio/c9_1_00_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"A horse likes to be with other horses.", "sp": "Holmes", "src": "audio/c9_1_01_00.mp3"}, {"t": "If he ran away, he went back to King's Pyland or to Mapleton.", "sp": "Holmes", "src": "audio/c9_1_01_01.mp3"}, {"t": "He is not at King's Pyland.", "sp": "Holmes", "src": "audio/c9_1_01_02.mp3"}, {"t": "So he must be at Mapleton.\"", "sp": "Holmes", "src": "audio/c9_1_01_03.mp3"}]}, {"kind": "p", "units": [{"t": "The ground near Mapleton was soft and wet.", "sp": "Watson", "src": "audio/c9_1_02_00.mp3"}, {"t": "I walked to the right, and Holmes walked to the left.", "sp": "Watson", "src": "audio/c9_1_02_01.mp3"}, {"t": "He shouted.", "sp": "Watson", "src": "audio/c9_1_02_02.mp3"}, {"t": "There was a horse's track.", "sp": "Watson", "src": "audio/c9_1_02_03.mp3"}, {"t": "Holmes took out the horseshoe.", "sp": "Watson", "src": "audio/c9_1_02_04.mp3"}, {"t": "It fitted exactly!", "sp": "Watson", "src": "audio/c9_1_02_05.mp3"}]}, {"kind": "p", "units": [{"t": "Later, we saw a man's track next to the horse's.", "sp": "Watson", "src": "audio/c9_1_03_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"The horse was alone before!\"", "sp": "Watson", "src": "audio/c9_1_04_00.mp3"}, {"t": "I cried.", "sp": "Watson", "src": "audio/c9_1_04_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Quite so,\"", "sp": "Holmes", "src": "audio/c9_1_05_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c9_1_05_01.mp3"}]}, {"kind": "p", "units": [{"t": "The tracks went towards King's Pyland.", "sp": "Watson", "src": "audio/c9_1_06_00.mp3"}, {"t": "Then I saw the same tracks coming back again.", "sp": "Watson", "src": "audio/c9_1_06_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"One for you, Watson,\"", "sp": "Holmes", "src": "audio/c9_1_07_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c9_1_07_01.mp3"}]}], "check": {"q": "홈즈는 왜 말이 메이플턴에 있을 거라고 생각했나요?", "a": "말은 다른 말들과 함께 있고 싶어 하는 동물이라, 도망쳤다면 원래 마구간이나 가까운 메이플턴으로 갔을 거예요. 킹스 파일랜드에는 없으니 메이플턴에 있다고 봤어요. 실제로 메이플턴 쪽에서 편자와 꼭 맞는 발자국을 찾았어요."}, "imgs": [{"at": 2, "src": "img/c9_a.svg"}]}, {"no": 2, "title": "메이플턴의 조련사", "paras": [{"kind": "p", "units": [{"t": "The tracks led to the gates of Mapleton.", "sp": "Watson", "src": "audio/c9_2_00_00.mp3"}, {"t": "An angry old man came out.", "sp": "Watson", "src": "audio/c9_2_00_01.mp3"}, {"t": "It was Silas Brown, the trainer.", "sp": "Watson", "src": "audio/c9_2_00_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"Go away, or you may find a dog at your heels!\"", "sp": "SilasBrown", "src": "audio/c9_2_01_00.mp3"}, {"t": "he shouted.", "sp": "Watson", "src": "audio/c9_2_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "Holmes whispered something in his ear.", "sp": "Watson", "src": "audio/c9_2_02_00.mp3"}, {"t": "Brown's face went red.", "sp": "Watson", "src": "audio/c9_2_02_01.mp3"}, {"t": "\"It's a lie!\"", "sp": "SilasBrown", "src": "audio/c9_2_02_02.mp3"}, {"t": "Then they went inside.", "sp": "Watson", "src": "audio/c9_2_02_03.mp3"}]}, {"kind": "p", "units": [{"t": "Twenty minutes later, they came out.", "sp": "Watson", "src": "audio/c9_2_03_00.mp3"}, {"t": "Brown's face was white, and his hands were shaking.", "sp": "Watson", "src": "audio/c9_2_03_01.mp3"}, {"t": "\"I will do what you say,\"", "sp": "SilasBrown", "src": "audio/c9_2_03_02.mp3"}, {"t": "he said.", "sp": "Watson", "src": "audio/c9_2_03_03.mp3"}]}, {"kind": "p", "units": [{"t": "On the way back, Holmes told me.", "sp": "Watson", "src": "audio/c9_2_04_00.mp3"}, {"t": "\"I told him everything he did that morning.", "sp": "Holmes", "src": "audio/c9_2_04_01.mp3"}, {"t": "He found Silver Blaze on the moor very early.", "sp": "Holmes", "src": "audio/c9_2_04_02.mp3"}, {"t": "He knew him by his white forehead.", "sp": "Holmes", "src": "audio/c9_2_04_03.mp3"}, {"t": "Then he hid him at Mapleton.\"", "sp": "Holmes", "src": "audio/c9_2_04_04.mp3"}]}], "check": {"q": "사일러스 브라운은 실버 블레이즈를 어떻게 하고 있었나요?", "a": "아침 일찍 황무지에 있던 실버 블레이즈를 흰 이마를 보고 알아봤고, 메이플턴에 몰래 숨겨 두었어요. 홈즈가 그걸 다 알아맞히자 얼굴이 하얘지고 시키는 대로 하겠다고 했어요."}, "imgs": [{"at": 0, "src": "img/c9_b.svg"}]}, {"no": 3, "title": "런던으로 돌아간다고?", "paras": [{"kind": "p", "units": [{"t": "\"Say nothing to the Colonel about the horse,\"", "sp": "Holmes", "src": "audio/c9_3_00_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c9_3_00_01.mp3"}]}, {"kind": "p", "units": [{"t": "At Straker's house, he said,", "sp": "Watson", "src": "audio/c9_3_01_00.mp3"}, {"t": "\"Watson and I are going back to London tonight.\"", "sp": "Holmes", "src": "audio/c9_3_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "The Colonel's lip curled.", "sp": "Watson", "src": "audio/c9_3_02_00.mp3"}, {"t": "\"So you can't find out what happened to poor Straker?\"", "sp": "Colonel", "src": "audio/c9_3_02_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"I hope your horse will run on Tuesday,\"", "sp": "Holmes", "src": "audio/c9_3_03_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c9_3_03_01.mp3"}, {"t": "\"May I have a photograph of Mr. Straker?\"", "sp": "Holmes", "src": "audio/c9_3_03_02.mp3"}]}, {"kind": "p", "units": [{"t": "The Inspector gave him one.", "sp": "Watson", "src": "audio/c9_3_04_00.mp3"}, {"t": "When Holmes left the room, the Colonel said,", "sp": "Watson", "src": "audio/c9_3_04_01.mp3"}, {"t": "\"I am disappointed in him.\"", "sp": "Colonel", "src": "audio/c9_3_04_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"At least he says your horse will run,\"", "sp": "Watson", "src": "audio/c9_3_05_00.mp3"}, {"t": "I said.", "sp": "Watson", "src": "audio/c9_3_05_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"I would rather have the horse.\"", "sp": "Colonel", "src": "audio/c9_3_06_00.mp3"}]}], "check": {"q": "로스 대령은 왜 홈즈에게 실망했나요?", "a": "홈즈가 스트레이커에게 무슨 일이 있었는지도 밝히지 않고, 말도 찾지 않은 채 런던으로 돌아간다고 했기 때문이에요. 대령은 홈즈가 말이 있는 곳을 이미 안다는 걸 몰라요. 홈즈가 왓슨에게 대령한테는 말하지 말라고 했거든요."}, "imgs": []}, {"no": 4, "title": "밤중의 개", "paras": [{"kind": "p", "units": [{"t": "As we got into the carriage, Holmes spoke to a stable boy.", "sp": "Watson", "src": "audio/c9_4_00_00.mp3"}, {"t": "\"You have some sheep.", "sp": "Holmes", "src": "audio/c9_4_00_01.mp3"}, {"t": "Is anything wrong with them?\"", "sp": "Holmes", "src": "audio/c9_4_00_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"Three of them have gone lame, sir.\"", "sp": "StableBoy", "src": "audio/c9_4_01_00.mp3"}]}, {"kind": "p", "units": [{"t": "Holmes was very pleased.", "sp": "Watson", "src": "audio/c9_4_02_00.mp3"}, {"t": "He laughed and rubbed his hands.", "sp": "Watson", "src": "audio/c9_4_02_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Is that important?\"", "sp": "Gregory", "src": "audio/c9_4_03_00.mp3"}, {"t": "asked the Inspector.", "sp": "Watson", "src": "audio/c9_4_03_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Very.\"", "sp": "Holmes", "src": "audio/c9_4_04_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"Is there anything else I should notice?\"", "sp": "Gregory", "src": "audio/c9_4_05_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"The curious incident of the dog in the night-time.\"", "sp": "Holmes", "src": "audio/c9_4_06_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"The dog did nothing in the night-time.\"", "sp": "Gregory", "src": "audio/c9_4_07_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"That was the curious incident,\"", "sp": "Holmes", "src": "audio/c9_4_08_00.mp3"}, {"t": "said Sherlock Holmes.", "sp": "Watson", "src": "audio/c9_4_08_01.mp3"}]}], "check": {"q": "경감은 \"그날 밤 개는 아무것도 안 했다\"고 했어요. 홈즈는 그게 왜 이상하다고 했을까요?", "a": "홈즈는 아직 설명하지 않았어요. 7장 단서 수첩의 개 이야기를 다시 읽고, 아래 「직접 풀어 보기」에서 먼저 생각해 봐요."}, "imgs": [{"at": 0, "src": "img/c9_c.svg"}]}], "solve": {"after": 4, "intro": ["여기서 잠깐 멈춰요. 단서 수첩을 펼쳐서 7장부터 모은 단서를 다시 읽어 보세요. 카레, 개, 칼과 성냥, 옷값 청구서, 다리 저는 양을 떠올려 봐요. 그리고 홈즈보다 먼저 답을 골라 봐요. 고른 답은 저장해 두었다가, 10장을 끝까지 읽은 뒤에 맞춰 봐요.", "정답은 10장 끝 「직접 풀어 보기 맞춰 보기」에 있어요."], "qs": [{"q": "그날 밤 실버 블레이즈를 마구간에서 데리고 나간 사람은 누구일까요? (Who took Silver Blaze out that night?)", "opts": ["① 낯선 남자 피츠로이 심슨 (Fitzroy Simpson)", "② 조련사 존 스트레이커 (John Straker)", "③ 메이플턴의 사일러스 브라운 (Silas Brown)", "④ 마구간 소년 네드 헌터 (Ned Hunter)"]}, {"q": "그날 밤 개는 왜 짖지 않았을까요? (Why did the dog do nothing?)", "opts": ["① 개도 약이 든 카레를 먹고 잠들어서", "② 비 소리가 너무 커서", "③ 말을 데리고 나간 사람이 개가 잘 아는 사람이라서", "④ 개가 다른 곳에 묶여 있어서"]}]}, "solve_answers": [{"answer": "②", "label": "조련사 존 스트레이커", "why": "홈즈가 \"Someone took a horse out of the stable, but the dog did not bark. So the visitor was someone the dog knew well. It was Straker himself.\"라고 설명해요. 카레를 고를 수 있었던 것도 스트레이커 부부뿐이었어요(\"Only Straker and his wife could.\"). ① 심슨은 낯선 사람이라 개가 가만있지 않았을 거예요. 7장에서 헌터는 심슨을 보자 개를 풀었어요."}, {"answer": "③", "label": "말을 데리고 나간 사람이 개가 잘 아는 사람이라서", "why": "\"So the visitor was someone the dog knew well.\" 개가 짖지 않은 것, 곧 '일어나지 않은 일'이 단서였어요. ① 약은 헌터의 카레에 넣었고, 개가 그 카레를 먹었다는 이야기는 없어요. ② 그날 밤 비가 왔지만, 비 소리 때문에 개가 못 들었다는 이야기는 없어요. ④ 개가 다른 곳에 있었다는 이야기도 없어요. 7장에서 헌터는 마구간 안에서 개를 풀었어요."}], "clues": [{"ko": "말 혼자 가던 발자국 옆에 사람 발자국이 붙어 메이플턴으로 갔어요. 사일러스 브라운이 실버 블레이즈를 숨겨 두었어요.", "en": "A man's track was next to the horse's. Silas Brown hid Silver Blaze at Mapleton."}, {"ko": "마구간 소년이 돌보는 양 가운데 세 마리가 다리를 절어요. 홈즈는 이 말을 듣고 아주 기뻐했어요.", "en": "Three sheep have gone lame. Holmes was very pleased."}, {"ko": "말이 사라진 그날 밤, 마구간의 개는 아무것도 하지 않았어요.", "en": "The dog did nothing in the night-time."}], "clue_intro": "오늘 읽은 내용에서 이 세 가지를 수첩에 적어 두세요. 「직접 풀어 보기」에서 쓸 거예요.", "quiz": [{"q": "Where did Holmes find Silver Blaze's track?", "ko": "홈즈는 실버 블레이즈의 발자국을 어디에서 찾았나요?", "opts": ["① in the stable at King's Pyland", "② on the road to Tavistock", "③ in the soft ground near Mapleton", "④ in Straker's garden"], "answer": "③", "why": "\"The ground near Mapleton was soft and wet. … There was a horse's track.\"라고 나와요. 홈즈의 편자가 그 발자국에 꼭 맞았어요."}, {"q": "What is wrong with the sheep?", "ko": "양들에게 무슨 일이 있나요?", "opts": ["① Three of them have gone lame.", "② They ran away.", "③ They are very fat.", "④ They are lost on the moor."], "answer": "①", "why": "마구간 소년이 \"Three of them have gone lame, sir.\"라고 답해요."}, {"q": "Why did Silas Brown's face go white?", "ko": "사일러스 브라운의 얼굴은 왜 하얘졌을까요?", "opts": ["① He was ill.", "② He was very cold.", "③ He lost his own horse.", "④ Holmes knew that he had hidden Silver Blaze."], "answer": "④", "why": "홈즈가 귀에 무언가를 속삭이자 \"It's a lie!\"라고 소리쳤지만, 이야기를 나눈 뒤에는 얼굴이 하얘지고 \"I will do what you say.\"라고 해요. 홈즈는 왓슨에게 \"I told him everything he did that morning.\"이라고 알려 줘요. 홈즈가 그가 한 일을 다 알고 있었던 거예요."}, {"q": "\"Three of them have gone lame.\" What does lame mean?", "ko": "여기서 lame은 무슨 뜻일까요?", "opts": ["① very hungry", "② lost", "③ very old", "④ walking badly because a leg hurts"], "answer": "④", "why": "양 다리가 아파서 잘 걷지 못한다는 뜻이에요. 왜 홈즈가 이 말에 기뻐했는지는 10장에서 나와요."}], "record": [{"t": "The horse was alone before!", "src": "audio/c9_r0.mp3", "sp": "Watson"}, {"t": "It fitted exactly!", "src": "audio/c9_r1.mp3", "sp": "Watson"}, {"t": "That was the curious incident.", "src": "audio/c9_r2.mp3", "sp": "Holmes"}], "think": "", "reflect": null, "cert": null, "end": null, "words_read": 399, "solve_reveal": 10}, "10": {"n": 10, "label": "10장", "title_en": "The Horse with No White Face", "title_ko": "흰 이마가 사라진 말", "new_text": false, "source": "원작: 아서 코난 도일, 「실버 블레이즈(Silver Blaze)」, 『셜록 홈즈의 회상록』(Project Gutenberg #834, 960~1222행). 초6 눈높이(CEFR A2~B1 초반)로 쉽게 고쳐 쓴 글이에요.", "recap_title": "지난 이야기", "recap": ["홈즈는 말발굽 자국을 따라가서, 메이플턴의 사일러스 브라운이 실버 블레이즈를 숨겨 두었다는 걸 알아냈어요. 하지만 로스 대령에게는 말하지 않고 런던으로 돌아가겠다고 했어요. 떠나기 전에 다리를 저는 양 이야기를 듣고 기뻐했고, \"밤중의 개에게 일어난 이상한 일\"을 말했어요."], "cards": [{"en": "Sherlock Holmes", "ko": "셜록 홈즈", "new": false, "line": "런던 베이커 가 221B에 사는 탐정이에요. 오늘 모든 수수께끼를 풀어요.", "img": "img/p_holmes.jpg"}, {"en": "Watson", "ko": "왓슨", "new": false, "line": "의사이고 홈즈의 친구예요. 이 이야기를 들려주는 '나(I)'예요.", "img": "img/p_watson.jpg"}, {"en": "Colonel Ross", "ko": "로스 대령", "new": false, "line": "실버 블레이즈의 주인이에요. 아직 자기 말을 보지 못해서 화가 나 있어요.", "img": "img/p_colonelross.svg"}, {"en": "Silver Blaze", "ko": "실버 블레이즈", "new": false, "line": "영국에서 가장 유명한 경주마예요. 이마의 흰 무늬와 얼룩이 있는 다리로 누구나 알아봐요.", "img": "img/p_silverblaze.svg"}, {"en": "John Straker", "ko": "존 스트레이커", "new": false, "line": "실버 블레이즈의 조련사였어요. 그날 밤 무슨 일이 있었는지 오늘 밝혀져요.", "img": "img/p_straker.svg"}], "words": [{"w": "frightened", "ko": "겁먹은, 놀란", "ex": "But the horse was frightened.", "why": "말이 스트레이커를 찬 까닭이에요.", "src": "audio/w_frightened.mp3", "exsrc": "audio/c10_v0.mp3"}, {"w": "wash", "ko": "씻다", "ex": "Wash his face and his leg.", "why": "씻으면 숨겨 둔 흰 무늬가 다시 나와요.", "src": "audio/w_wash.mp3", "exsrc": "audio/c10_v1.mp3"}, {"w": "protect", "ko": "지키다", "ex": "And he did it to protect himself.", "why": "말은 자기 몸을 지키려다 스트레이커를 찼어요.", "src": "audio/w_protect.mp3", "exsrc": "audio/c10_v2.mp3"}, {"w": "taste", "ko": "맛", "ex": "The drug has a taste, but curry hides it.", "why": "카레가 왜 첫 번째 단서인지 알려 줘요.", "src": "audio/w_taste.mp3", "exsrc": "audio/c10_v3.mp3"}, {"w": "bark", "ko": "짖다", "ex": "Someone took a horse out of the stable, but the dog did not bark.", "why": "짖지 않은 개가 가장 유명한 단서예요.", "src": "audio/w_bark.mp3", "exsrc": "audio/c10_v4.mp3"}, {"w": "practise", "ko": "연습하다", "ex": "Straker practised on them first.", "why": "다리 저는 양의 비밀이에요.", "src": "audio/w_practise.mp3", "exsrc": "audio/c10_v5.mp3"}, {"w": "debt", "ko": "빚", "ex": "He had big secret debts.", "why": "스트레이커가 나쁜 일을 꾸민 까닭이에요.", "src": "audio/w_debt.mp3", "exsrc": "audio/c10_v6.mp3"}], "scenes": [{"no": 1, "title": "웨섹스 컵 경주", "paras": [{"kind": "p", "units": [{"t": "Four days later, we went to the race for the Wessex Cup.", "sp": "Watson", "src": "audio/c10_1_00_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"I have seen nothing of my horse,\"", "sp": "Colonel", "src": "audio/c10_1_01_00.mp3"}, {"t": "said Colonel Ross coldly.", "sp": "Watson", "src": "audio/c10_1_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Would you know him if you saw him?\"", "sp": "Holmes", "src": "audio/c10_1_02_00.mp3"}, {"t": "asked Holmes.", "sp": "Watson", "src": "audio/c10_1_02_01.mp3"}]}, {"kind": "p", "units": [{"t": "The Colonel was angry.", "sp": "Watson", "src": "audio/c10_1_03_00.mp3"}, {"t": "\"A child would know Silver Blaze, with his white forehead and his spotted leg!\"", "sp": "Colonel", "src": "audio/c10_1_03_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"All six horses are there,\"", "sp": "Watson", "src": "audio/c10_1_04_00.mp3"}, {"t": "I said.", "sp": "Watson", "src": "audio/c10_1_04_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Then my horse is running,\"", "sp": "Colonel", "src": "audio/c10_1_05_00.mp3"}, {"t": "cried the Colonel.", "sp": "Watson", "src": "audio/c10_1_05_01.mp3"}, {"t": "\"But I don't see him.\"", "sp": "Colonel", "src": "audio/c10_1_05_02.mp3"}]}, {"kind": "p", "units": [{"t": "A strong brown horse ran past us in the Colonel's colours.", "sp": "Watson", "src": "audio/c10_1_06_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"That's not my horse!\"", "sp": "Colonel", "src": "audio/c10_1_07_00.mp3"}, {"t": "cried the Colonel.", "sp": "Watson", "src": "audio/c10_1_07_01.mp3"}, {"t": "\"It does not have one white hair!\"", "sp": "Colonel", "src": "audio/c10_1_07_02.mp3"}]}, {"kind": "p", "units": [{"t": "The race began.", "sp": "Watson", "src": "audio/c10_1_08_00.mp3"}, {"t": "The horse in the Colonel's colours won easily!", "sp": "Watson", "src": "audio/c10_1_08_01.mp3"}]}], "check": {"q": "대령은 왜 \"저건 내 말이 아니다\"라고 했나요?", "a": "대령의 색(the Colonel's colours)을 달고 달린 말에 흰 털이 하나도 없었기 때문이에요. 실버 블레이즈는 이마의 흰 무늬로 누구나 알아보는 말이거든요. 그런데 그 말이 경주에서 이겼어요."}, "imgs": [{"at": 8, "src": "img/c10_a.svg"}]}, {"no": 2, "title": "진짜 범인", "paras": [{"kind": "p", "units": [{"t": "\"Wash his face and his leg,\"", "sp": "Holmes", "src": "audio/c10_2_00_00.mp3"}, {"t": "said Holmes,", "sp": "Watson", "src": "audio/c10_2_00_01.mp3"}, {"t": "\"and you will find Silver Blaze.", "sp": "Holmes", "src": "audio/c10_2_00_02.mp3"}, {"t": "I found him with a man who had changed the horse's looks.", "sp": "Holmes", "src": "audio/c10_2_00_03.mp3"}, {"t": "I let him run as he was.\"", "sp": "Holmes", "src": "audio/c10_2_00_04.mp3"}]}, {"kind": "p", "units": [{"t": "\"You have done wonders!\"", "sp": "Colonel", "src": "audio/c10_2_01_00.mp3"}, {"t": "said the Colonel.", "sp": "Watson", "src": "audio/c10_2_01_01.mp3"}, {"t": "\"Now, can you find the one who caused Straker's death?\"", "sp": "Colonel", "src": "audio/c10_2_01_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"I have,\"", "sp": "Holmes", "src": "audio/c10_2_02_00.mp3"}, {"t": "said Holmes.", "sp": "Watson", "src": "audio/c10_2_02_01.mp3"}, {"t": "\"He is standing right behind you.\"", "sp": "Holmes", "src": "audio/c10_2_02_02.mp3"}, {"t": "He put his hand on the horse's neck.", "sp": "Watson", "src": "audio/c10_2_02_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"The horse!\"", "sp": "Colonel", "src": "audio/c10_2_03_00.mp3"}, {"t": "cried the Colonel and I.", "sp": "Watson", "src": "audio/c10_2_03_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Yes, the horse.", "sp": "Holmes", "src": "audio/c10_2_04_00.mp3"}, {"t": "And he did it to protect himself.\"", "sp": "Holmes", "src": "audio/c10_2_04_01.mp3"}]}], "check": {"q": "홈즈는 스트레이커를 죽게 한 것이 누구라고 했나요?", "a": "사람이 아니라 실버 블레이즈였어요. 그것도 자기 몸을 지키려다 그랬대요. 어떻게 된 일인지는 다음 장면에서 홈즈가 설명해요."}, "imgs": [{"at": 2, "src": "img/c10_b.svg"}]}, {"no": 3, "title": "카레와 개", "paras": [{"kind": "p", "units": [{"t": "On the train, Holmes explained.", "sp": "Watson", "src": "audio/c10_3_00_00.mp3"}]}, {"kind": "p", "units": [{"t": "\"The curry was my first clue.", "sp": "Holmes", "src": "audio/c10_3_01_00.mp3"}, {"t": "The drug has a taste, but curry hides it.", "sp": "Holmes", "src": "audio/c10_3_01_01.mp3"}, {"t": "A stranger could not choose curry for supper that night.", "sp": "Holmes", "src": "audio/c10_3_01_02.mp3"}, {"t": "Only Straker and his wife could.", "sp": "Holmes", "src": "audio/c10_3_01_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"Then there was the dog.", "sp": "Holmes", "src": "audio/c10_3_02_00.mp3"}, {"t": "Someone took a horse out of the stable, but the dog did not bark.", "sp": "Holmes", "src": "audio/c10_3_02_01.mp3"}, {"t": "So the visitor was someone the dog knew well.", "sp": "Holmes", "src": "audio/c10_3_02_02.mp3"}, {"t": "It was Straker himself.", "sp": "Holmes", "src": "audio/c10_3_02_03.mp3"}]}], "check": {"q": "홈즈는 왜 카레가 첫 번째 단서라고 했나요?", "a": "약에는 맛이 있는데, 카레는 그 맛을 감춰 줘요. 낯선 사람은 그날 저녁 메뉴를 정할 수 없어요. 카레를 고를 수 있었던 건 스트레이커 부부뿐이에요."}, "imgs": [{"at": 0, "src": "img/c10_c.svg"}]}, {"no": 4, "title": "칼, 성냥, 그리고 양", "paras": [{"kind": "p", "units": [{"t": "\"Straker planned to hurt the horse's leg a little with that fine knife.", "sp": "Holmes", "src": "audio/c10_4_00_00.mp3"}, {"t": "Then the horse would lose the race.", "sp": "Holmes", "src": "audio/c10_4_00_01.mp3"}, {"t": "So he went out on the moor.\"", "sp": "Holmes", "src": "audio/c10_4_00_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"That is why he had the candle and the matches!\"", "sp": "Colonel", "src": "audio/c10_4_01_00.mp3"}, {"t": "cried the Colonel.", "sp": "Watson", "src": "audio/c10_4_01_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"Yes.", "sp": "Holmes", "src": "audio/c10_4_02_00.mp3"}, {"t": "And Mrs. Straker never had that dress.", "sp": "Holmes", "src": "audio/c10_4_02_01.mp3"}, {"t": "So who was Derbyshire?", "sp": "Holmes", "src": "audio/c10_4_02_02.mp3"}]}, {"kind": "p", "units": [{"t": "\"Straker took Silver Blaze to the hollow.", "sp": "Holmes", "src": "audio/c10_4_03_00.mp3"}, {"t": "Simpson had dropped his tie, and Straker picked it up.", "sp": "Holmes", "src": "audio/c10_4_03_01.mp3"}, {"t": "He took off his coat and lit a match.", "sp": "Holmes", "src": "audio/c10_4_03_02.mp3"}, {"t": "But the horse was frightened.", "sp": "Holmes", "src": "audio/c10_4_03_03.mp3"}, {"t": "He kicked out and hit Straker.", "sp": "Holmes", "src": "audio/c10_4_03_04.mp3"}]}, {"kind": "p", "units": [{"t": "\"The lame sheep?", "sp": "Holmes", "src": "audio/c10_4_04_00.mp3"}, {"t": "Straker practised on them first.", "sp": "Holmes", "src": "audio/c10_4_04_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"At the dress shop, they knew Straker's photograph.", "sp": "Holmes", "src": "audio/c10_4_05_00.mp3"}, {"t": "Derbyshire was Straker.", "sp": "Holmes", "src": "audio/c10_4_05_01.mp3"}, {"t": "He had big secret debts.", "sp": "Holmes", "src": "audio/c10_4_05_02.mp3"}, {"t": "His debts led him into this plan.\"", "sp": "Holmes", "src": "audio/c10_4_05_03.mp3"}]}, {"kind": "p", "units": [{"t": "\"Where was my horse?\"", "sp": "Colonel", "src": "audio/c10_4_06_00.mp3"}, {"t": "asked the Colonel.", "sp": "Watson", "src": "audio/c10_4_06_01.mp3"}]}, {"kind": "p", "units": [{"t": "\"He ran away, and one of your neighbours looked after him.\"", "sp": "Holmes", "src": "audio/c10_4_07_00.mp3"}]}], "check": {"q": "스트레이커는 그날 밤 무엇을 하려고 했나요?", "a": "그 얇은 칼로 말 다리를 조금 다치게 해서 경주에서 지게 하려고 했어요. 홈즈 말로는 몰래 진 큰 빚 때문이었어요. 그런데 성냥을 켜자 놀란 말이 발로 찼어요. 다리 저는 양은 미리 연습한 흔적이었어요."}, "imgs": []}], "solve": null, "solve_answers": [], "clues": [{"ko": "카레는 약 맛을 감추려고 고른 음식이에요. 그날 저녁 카레를 고를 수 있던 사람은 스트레이커 부부뿐이에요.", "en": "Curry hides the taste of the drug. Only Straker and his wife could choose curry."}, {"ko": "개가 짖지 않았으니, 밤에 말을 데리고 나간 사람은 개가 잘 아는 사람이에요. 바로 스트레이커예요.", "en": "The dog did not bark, so the visitor was someone the dog knew well: Straker."}, {"ko": "스트레이커는 몰래 진 큰 빚 때문에 말 다리를 조금 다치게 해서 경주에서 지게 하려 했어요. 양으로 먼저 연습했어요.", "en": "Straker had secret debts. He planned to hurt the horse's leg a little. He practised on the sheep first."}], "clue_intro": "오늘은 지금까지 모은 단서가 하나로 이어져요. 이 세 가지를 수첩에 적어 두세요.", "quiz": [{"q": "Why couldn't the Colonel see his horse at the race?", "ko": "대령은 왜 경주에서 자기 말을 알아보지 못했나요?", "opts": ["① The horse did not come to the race.", "② The horse was sick.", "③ The horse was too far away.", "④ The horse's white forehead and spotted leg were hidden."], "answer": "④", "why": "대령은 실버 블레이즈를 흰 이마와 얼룩진 다리로 알아본다고 했어요. 그런데 경주에 나온 말을 보고는 \"It does not have one white hair!\"라고 외쳤어요. 홈즈가 \"Wash his face and his leg … and you will find Silver Blaze.\"라고 해요. 누군가 생김새를 바꿔 놓았던 거예요."}, {"q": "What was Holmes's first clue?", "ko": "홈즈의 첫 번째 단서는 무엇이었나요?", "opts": ["① the tie", "② the curry", "③ the horseshoe", "④ the photograph"], "answer": "②", "why": "홈즈가 \"The curry was my first clue.\"라고 말해요."}, {"q": "Why did the horse kick Straker?", "ko": "말은 왜 스트레이커를 찼나요?", "opts": ["① It was frightened.", "② It was hungry.", "③ It wanted to run home.", "④ Simpson hit it."], "answer": "①", "why": "\"He took off his coat and lit a match. But the horse was frightened. He kicked out and hit Straker.\" 홈즈는 말이 \"to protect himself\", 곧 자기 몸을 지키려고 그랬다고 해요."}, {"q": "\"He had big secret debts.\" What are debts?", "ko": "여기서 debts는 무엇일까요?", "opts": ["① secret friends", "② expensive dresses", "③ racehorses", "④ money that you must pay back"], "answer": "④", "why": "빌린 돈이나 갚아야 할 돈을 빚이라고 해요. 홈즈는 \"His debts led him into this plan.\", 곧 이 빚 때문에 스트레이커가 나쁜 일을 꾸몄다고 해요."}], "record": [{"t": "A child would know Silver Blaze!", "src": "audio/c10_r0.mp3", "sp": "Colonel"}, {"t": "He is standing right behind you.", "src": "audio/c10_r1.mp3", "sp": "Holmes"}, {"t": "The curry was my first clue.", "src": "audio/c10_r2.mp3", "sp": "Holmes"}], "think": "", "reflect": null, "cert": null, "end": null, "words_read": 398, "solve_check_for": 9}, "11": {"n": 11, "label": "에필로그", "title_en": "Your Turn, Detective", "title_ko": "이제 네 차례야", "new_text": false, "source": "이 장은 원작에 없는 글이에요. 세 사건을 한 권으로 묶으려고 새로 썼어요. 새로운 사건 내용은 넣지 않았고, 앞에서 읽은 세 사건에 나온 사실만 썼어요.", "recap_title": "시작하기 전에", "recap": ["세 사건을 모두 읽었어요. 마지막으로 왓슨이 세 사건을 함께 돌아보고, 여러분에게 수첩을 넘겨줘요. 다 읽으면 한 줄 감상을 쓰고 수료증을 받아요."], "cards": [{"en": "Sherlock Holmes", "ko": "셜록 홈즈", "new": false, "line": "런던 베이커 가 221B에 사는 탐정이에요. 사람, 물건, 그리고 일어나지 않은 일에서 단서를 찾았어요.", "img": "img/p_holmes.jpg"}, {"en": "Watson", "ko": "왓슨", "new": false, "line": "의사이고 홈즈의 친구예요. 세 사건을 수첩에 적어 여러분에게 들려줬어요.", "img": "img/p_watson.jpg"}], "words": [{"w": "look back", "ko": "돌아보다", "ex": "Let me look back at them with you.", "why": "세 사건을 처음부터 다시 떠올려요.", "src": "audio/w_look back.mp3", "exsrc": "audio/c11_v0.mp3"}, {"w": "happen", "ko": "일어나다", "ex": "Holmes looked at something that did not happen.", "why": "일어나지 않은 일도 단서가 돼요.", "src": "audio/w_happen.mp3", "exsrc": "audio/c11_v1.mp3"}, {"w": "missing", "ko": "없는, 빠진", "ex": "Sometimes a clue is something that is missing.", "why": "이 책에서 배운 가장 중요한 탐정 기술이에요.", "src": "audio/w_missing.mp3", "exsrc": "audio/c11_v2.mp3"}, {"w": "remember", "ko": "기억하다", "ex": "Which scene do you remember best?", "why": "한 줄 감상에서 답할 질문이에요.", "src": "audio/w_remember.mp3", "exsrc": "audio/c11_v3.mp3"}], "scenes": [{"no": 1, "title": "세 사건을 돌아보며", "paras": [{"kind": "p", "units": [{"t": "Our three cases are over.", "sp": "Watson", "src": "audio/c11_1_00_00.mp3"}, {"t": "Let me look back at them with you.", "sp": "Watson", "src": "audio/c11_1_00_01.mp3"}]}, {"kind": "p", "units": [{"t": "In the first case, Holmes looked at people.", "sp": "Watson", "src": "audio/c11_1_01_00.mp3"}, {"t": "He saw a fish tattoo on a wrist.", "sp": "Watson", "src": "audio/c11_1_01_01.mp3"}, {"t": "He also saw the knees of an assistant's trousers.", "sp": "Watson", "src": "audio/c11_1_01_02.mp3"}]}, {"kind": "p", "units": [{"t": "In the second case, Holmes looked at a thing.", "sp": "Watson", "src": "audio/c11_1_02_00.mp3"}, {"t": "An old hat told him about its owner.", "sp": "Watson", "src": "audio/c11_1_02_01.mp3"}]}, {"kind": "p", "units": [{"t": "In the third case, Holmes looked at something that did not happen.", "sp": "Watson", "src": "audio/c11_1_03_00.mp3"}, {"t": "The dog did nothing in the night-time.", "sp": "Watson", "src": "audio/c11_1_03_01.mp3"}]}, {"kind": "p", "units": [{"t": "So a clue is not only something you can see.", "sp": "Watson", "src": "audio/c11_1_04_00.mp3"}, {"t": "Sometimes a clue is something that is missing.", "sp": "Watson", "src": "audio/c11_1_04_01.mp3"}]}], "check": {"q": "세 번째 사건에서 홈즈가 찾은 단서는 어떤 단서였나요?", "a": "일어나지 않은 일이에요. 그날 밤 개가 아무것도 하지 않은 것, 곧 짖지 않은 것이 단서였어요. 단서는 눈에 보이는 것만이 아니라 '없는 것'일 때도 있어요."}, "imgs": [{"at": 0, "src": "img/c11_a.svg"}]}, {"no": 2, "title": "이제 네 차례야", "paras": [{"kind": "p", "units": [{"t": "Do you remember what Holmes said to me?", "sp": "Watson", "src": "audio/c11_2_00_00.mp3"}, {"t": "\"You can see everything.", "sp": "Watson", "src": "audio/c11_2_00_01.mp3"}, {"t": "But you do not think about what you see.\"", "sp": "Watson", "src": "audio/c11_2_00_02.mp3"}]}, {"kind": "p", "units": [{"t": "Now it is your turn, detective.", "sp": "Watson", "src": "audio/c11_2_01_00.mp3"}, {"t": "Look at small things.", "sp": "Watson", "src": "audio/c11_2_01_01.mp3"}, {"t": "Think about what you see.", "sp": "Watson", "src": "audio/c11_2_01_02.mp3"}, {"t": "Write your clues in your notebook.", "sp": "Watson", "src": "audio/c11_2_01_03.mp3"}]}, {"kind": "p", "units": [{"t": "Before you go, please write one line for me.", "sp": "Watson", "src": "audio/c11_2_02_00.mp3"}, {"t": "Which scene do you remember best?", "sp": "Watson", "src": "audio/c11_2_02_01.mp3"}]}, {"kind": "p", "units": [{"t": "Thank you for reading my notebook.", "sp": "Watson", "src": "audio/c11_2_03_00.mp3"}]}], "check": {"q": "왓슨은 마지막으로 여러분에게 무엇을 부탁했나요?", "a": "작은 것을 보고, 본 것을 가지고 생각하고, 단서를 수첩에 적으라고 했어요. 그리고 가장 기억에 남는 장면을 한 줄로 써 달라고 했어요."}, "imgs": [{"at": 0, "src": "img/c11_b.svg"}]}], "solve": null, "solve_answers": [], "clues": [], "clue_intro": "", "quiz": [], "record": [], "think": "", "reflect": {"q": "이 책에서 가장 기억에 남는 장면은 무엇인가요? 한 줄로 써 봐요.", "help": "어느 사건의 어떤 장면인지, 왜 기억에 남는지 한 줄이면 충분해요. 예: \"나는 ___ 장면이 기억에 남아요. 왜냐하면 ___.\""}, "cert": {"title": "명탐정 수료증 · Great Detective Certificate", "body": "{이름} 탐정은 「왓슨의 사건 수첩: 셜록 홈즈의 세 사건」을 끝까지 읽었습니다. 빨간 머리 연맹, 푸른 석류석, 실버 블레이즈 세 사건을 따라가며 영어 {읽은 단어 수}단어를 읽고 단서 {모은 단서 수}개를 모았습니다. 이 수첩의 주인에게 명탐정 칭호를 드립니다.", "foot": "{끝낸 날짜} · 리드앤라이트 영어교습소 · 담당 {선생님 이름}"}, "end": {"title": "세 사건 수사를 마쳤어요", "items": ["책 한 권을 끝까지 읽어 낸 것만으로도 대단한 일이에요.", "리드앤라이트에 등록하면 10% 할인해 드려요. (무료코스 수료 할인)", "등록하면 이번 코스 기록을 바탕으로 만든 진단 자료를 드려요.", "레벨테스트: 11월 2일~6일, 11월 9일~13일", "문의: 0507-1312-1196", "리드앤라이트 영어교습소 · 교습소 신고번호 제3-가-05019호"]}, "words_read": 155}}};
